-- Schema-only fixture shared by the Cloudshop-derived applications. No customer rows or credentials.
create sequence if not exists public.sales_order_number_seq;
create sequence if not exists public.stock_materials_id_seq;
create sequence if not exists public.stock_norms_id_seq;
create sequence if not exists public.stock_moves_id_seq;
create sequence if not exists public.announcement_changes_id_seq;
create sequence if not exists public.stock_requests_id_seq;
create table public.announcement_changes (id bigint not null, source text not null, item_key text not null, item_name text not null, kind text not null, old_price numeric, new_price numeric, status text not null, announcement_id bigint, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table public.announcement_reads (announcement_id bigint not null, person_id bigint not null, shift_id bigint, read_at timestamp with time zone not null);
create table public.announcements (id bigint generated by default as identity not null, title text not null, body text, is_active boolean not null, created_at timestamp with time zone not null);
create table public.branch_checks (id bigint generated by default as identity not null, branch_id bigint not null, check_date date not null, product text not null, payment text not null, deadline text not null, contacts text not null, readiness text not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, created_by uuid, order_no text not null);
create table public.customer_debts (id bigint generated by default as identity not null, sale_id bigint not null, customer_id uuid not null, amount numeric(12,2) not null, created_at timestamp with time zone not null, paid_at timestamp with time zone);
create table public.guide_questions (id bigint generated by default as identity not null, product_id uuid not null, question text not null, options jsonb not null, correct_index integer not null, sort_order integer not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table public.guide_test_results (id bigint generated by default as identity not null, product_id uuid, person_id bigint, person_name text not null, score integer not null, total integer not null, wrong jsonb not null, created_at timestamp with time zone not null);
create table public.loyalty_customers (id uuid not null, name text not null, phone text not null, comment text, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, created_by_employee_id bigint);
create table public.loyalty_gift_rules (id bigint generated by default as identity not null, order_count integer not null, gift_name text not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table public.loyalty_transactions (id bigint generated by default as identity not null, customer_id uuid not null, transaction_type text not null, order_amount numeric(12,2) not null, points numeric(12,2) not null, comment text, available_at timestamp with time zone not null, created_at timestamp with time zone not null, gift_rule_id bigint);
create table public.message_templates (id uuid not null, title text not null, category text, body text not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, sort_order integer);
create table public.pickup_orders (id bigint generated by default as identity not null, branch_id bigint not null, shift_id bigint, employee_id bigint, order_number bigint, items jsonb not null, gross_total numeric(12,2) not null, discount_percent numeric not null, total numeric(12,2) not null, customer_id uuid, client_name text, client_phone text, comment text, status text not null, created_at timestamp with time zone not null, paid_at timestamp with time zone, paid_shift_id bigint, sale_id bigint, cancelled_at timestamp with time zone, cancel_reason text, client_order_ref text);
create table public.plotter_film_prices (id uuid not null, color text not null, sheet_width_cm numeric not null, sheet_length_cm numeric not null, price numeric not null, created_at timestamp with time zone not null);
create table public.products (id uuid not null, name text not null, sku text, category text, description text, tags text[], image_url text, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, sort_order integer);
create table public.report_fills (id bigint generated by default as identity not null, shift_id bigint not null, branch_id bigint not null, day date not null, mode text not null, sheet_id bigint, row_no integer, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table public.report_import (sheet_no integer not null, part integer not null, body text not null);
create table public.report_recipients (chat_id bigint not null, name text, active boolean not null, created_at timestamp with time zone not null);
create table public.report_sheets (id bigint generated by default as identity not null, sort_order integer not null, title text not null, branch_id bigint, data jsonb not null, months jsonb not null, updated_at timestamp with time zone not null, staff_visible boolean not null);
create table public.sale_items (id bigint generated by default as identity not null, sale_id bigint not null, catalog_id bigint, item_type text not null, item_name text not null, quantity numeric(12,3) not null, unit_price numeric(12,2) not null, line_total numeric(12,2) not null, cost_price numeric(12,2), cost_total numeric(12,2), variant_material_id bigint);
create table public.sale_payments (id bigint generated by default as identity not null, sale_id bigint not null, payment_method text not null, amount numeric(12,2) not null, created_at timestamp with time zone not null);
create table public.sales (id bigint generated by default as identity not null, shift_id bigint not null, branch_id bigint not null, employee_id bigint not null, payment_method text not null, total numeric(12,2) not null, comment text, status text not null, created_at timestamp with time zone not null, returned_at timestamp with time zone, gross_total numeric(12,2), loyalty_points_used numeric(12,2) not null, loyalty_customer_id uuid, receipt_issued boolean, order_number bigint, discount_percent numeric(8,2) not null, discount_amount numeric(12,2) not null, payment_status text not null, paid_at timestamp with time zone, cancelled_at timestamp with time zone, client_uid uuid, offline_at timestamp with time zone);
