create table public.sales_catalog (id bigint generated by default as identity not null, item_type text not null, name text not null, sku text, price numeric(12,2) not null, is_active boolean not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null, cost_price numeric(12,2), category text, comment text, wholesale_prices jsonb not null, image_url text);
create table public.sales_employees (id bigint generated by default as identity not null, branch_id bigint not null, name text not null, is_active boolean not null, created_at timestamp with time zone not null, person_id bigint not null);
create table public.sales_pay_rates (id bigint generated by default as identity not null, employee_id bigint not null, branch_id bigint not null, shift_rate numeric(12,2) not null, retouch_rate numeric(12,2) not null, is_active boolean not null);
create table public.sales_payroll_weeks (id bigint generated by default as identity not null, week_start date not null, week_end date not null, pay_date date not null, created_at timestamp with time zone not null);
create table public.sales_people (id bigint generated by default as identity not null, name text not null, is_active boolean not null, created_at timestamp with time zone not null, retouch_lead_default boolean not null);
create table public.sales_person_tasks (id bigint generated by default as identity not null, person_id bigint not null, title text not null, description text, start_date date not null, is_active boolean not null, created_at timestamp with time zone not null, completed_at timestamp with time zone, completed_shift_id bigint, completed_by_employee_id bigint);
create table public.sales_returns (id bigint generated by default as identity not null, sale_id bigint not null, shift_id bigint not null, branch_id bigint not null, employee_id bigint not null, amount numeric(12,2) not null, comment text, created_at timestamp with time zone not null);
create table public.sales_shift_employees (id bigint generated by default as identity not null, shift_id bigint not null, employee_id bigint not null, is_lead boolean not null, created_at timestamp with time zone not null);
create table public.sales_shift_task_completions (id bigint generated by default as identity not null, task_id bigint not null, shift_id bigint not null, completed_by_employee_id bigint not null, completed_at timestamp with time zone not null);
