create table public.sales_shifts (id bigint generated by default as identity not null, branch_id bigint not null, employee_id bigint not null, started_at timestamp with time zone not null, ended_at timestamp with time zone, status text not null, open_cash numeric(12,2), open_cash_expected numeric(12,2), open_cash_at timestamp with time zone, open_cash_employee_id bigint, close_cash numeric(12,2), close_cash_employee_id bigint, no_pay boolean not null);
create table public.sales_upsell_rules (id bigint generated by default as identity not null, source_catalog_id bigint not null, suggested_catalog_id bigint not null, min_quantity numeric(12,3) not null, max_quantity numeric(12,3), question text not null, is_active boolean not null, created_at timestamp with time zone not null);
create table public.schedule_cells (work_date date not null, column_id bigint not null, slot smallint not null, person_id bigint, updated_at timestamp with time zone not null);
create table public.schedule_columns (id bigint generated by default as identity not null, title text not null, branch_id bigint, sort_order integer not null, slots smallint not null, need_weekday smallint not null, need_weekend smallint not null, is_active boolean not null, created_at timestamp with time zone not null);
