CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
  select exists(select 1 from public.staff_accounts s where s.user_id = auth.uid() and s.active and s.role = 'admin');
$function$;
CREATE OR REPLACE FUNCTION public.is_staff()
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
  select exists(select 1 from public.staff_accounts s where s.user_id = auth.uid() and s.active);
$function$;
CREATE OR REPLACE FUNCTION public.is_test_branch(p_id bigint)
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce((select is_test from public.sales_branches where id=p_id),false)
$function$;
CREATE OR REPLACE FUNCTION public.kassa_cash_check_enabled()
 RETURNS boolean LANGUAGE sql IMMUTABLE
AS $function$ select false $function$;

CREATE OR REPLACE FUNCTION public.admin_period_summary(p_from timestamp with time zone, p_to timestamp with time zone, p_prev_from timestamp with time zone, p_prev_to timestamp with time zone, p_branch_id bigint DEFAULT NULL::bigint, p_bucket text DEFAULT 'day'::text, p_tz text DEFAULT 'Europe/Moscow'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; v_step interval;
begin
  if not public.is_admin() then raise exception 'Сводка доступна только администратору'; end if;
  if p_bucket not in ('hour','day','week','month') then raise exception 'Некорректная группировка'; end if;
  v_step:=('1 '||p_bucket)::interval;
  with s as (
    select x.*, case when x.created_at>=p_from and x.created_at<p_to then 'cur' else 'prev' end as per
    from public.sales x
    where ((x.created_at>=p_from and x.created_at<p_to) or (x.created_at>=p_prev_from and x.created_at<p_prev_to)) and x.status='completed' and x.payment_status<>'unpaid'
      and (p_branch_id is null or x.branch_id=p_branch_id) and not public.is_test_branch(x.branch_id)
  ), it as (
    select i.*, s.per, coalesce(nullif(c.category,''),'Без категории') as cat
    from public.sale_items i join s on s.id=i.sale_id left join public.sales_catalog c on c.id=i.catalog_id
  ), tot as (
    select per, sum(total) rev, count(*) cnt, sum(discount_amount) disc, sum(loyalty_points_used) pts,
      count(*) filter (where loyalty_customer_id is not null) club
    from s group by per
  ), costs as (select per, sum(coalesce(cost_total,0)) cost, count(*) filter (where cost_price is null) no_cost from it group by per),
  rets as (
    select case when r.created_at>=p_from and r.created_at<p_to then 'cur' else 'prev' end per, sum(r.amount) amt, count(*) cnt
    from public.sales_returns r where ((r.created_at>=p_from and r.created_at<p_to) or (r.created_at>=p_prev_from and r.created_at<p_prev_to)) and (p_branch_id is null or r.branch_id=p_branch_id) and not public.is_test_branch(r.branch_id) group by 1
  ), newc as (
    select case when c.created_at>=p_from and c.created_at<p_to then 'cur' else 'prev' end per, count(*) cnt
    from public.loyalty_customers c where (c.created_at>=p_from and c.created_at<p_to) or (c.created_at>=p_prev_from and c.created_at<p_prev_to) group by 1
  ), sh as (
    select case when x.started_at>=p_from and x.started_at<p_to then 'cur' else 'prev' end per, count(*) cnt
    from public.sales_shifts x where ((x.started_at>=p_from and x.started_at<p_to) or (x.started_at>=p_prev_from and x.started_at<p_prev_to)) and (p_branch_id is null or x.branch_id=p_branch_id) and not public.is_test_branch(x.branch_id) group by 1
  ), per_obj as (
    select p.per, jsonb_build_object('revenue',coalesce(t.rev,0),'count',coalesce(t.cnt,0),'discount',coalesce(t.disc,0),'points',coalesce(t.pts,0),
      'club',coalesce(t.club,0),'cost',coalesce(c.cost,0),'noCostItems',coalesce(c.no_cost,0),'returns',coalesce(r.amt,0),'returnsCount',coalesce(r.cnt,0),
      'newCustomers',coalesce(n.cnt,0),'shifts',coalesce(h.cnt,0)) o
    from (values('cur'),('prev')) p(per)
    left join tot t on t.per=p.per left join costs c on c.per=p.per left join rets r on r.per=p.per
    left join newc n on n.per=p.per left join sh h on h.per=p.per
  ), items as (
    select item_name name, max(cat) cat,
      sum(quantity) filter (where per='cur') qty, sum(line_total) filter (where per='cur') rev, sum(cost_total) filter (where per='cur') cost,
      sum(quantity) filter (where per='prev') pqty, sum(line_total) filter (where per='prev') prev
    from it group by item_name
  ), cats as (
    select cat name, sum(line_total) filter (where per='cur') rev, sum(line_total) filter (where per='prev') prev from it group by cat
  ), br as (
    select coalesce(b.name,'?') name, sum(s.total) filter (where per='cur') rev, count(*) filter (where per='cur') cnt,
      sum(s.total) filter (where per='prev') prev, count(*) filter (where per='prev') pcnt
    from s left join public.sales_branches b on b.id=s.branch_id group by 1
  ), em as (
    select coalesce(pp.name,e.name,'?') name, sum(s.total) filter (where per='cur') rev, count(*) filter (where per='cur') cnt,
      sum(s.total) filter (where per='prev') prev, count(*) filter (where per='prev') pcnt
    from s left join public.sales_employees e on e.id=s.employee_id left join public.sales_people pp on pp.id=e.person_id group by 1
  ), pay as (
    select p.payment_method m, sum(p.amount) filter (where s.per='cur') amt, sum(p.amount) filter (where s.per='prev') prev
    from public.sale_payments p join s on s.id=p.sale_id group by 1
  ), cur_b as (
    select g b from generate_series(date_trunc(p_bucket,p_from at time zone p_tz), (p_to at time zone p_tz)-interval '1 second', v_step) g
  ), prev_b as (
    select g b from generate_series(date_trunc(p_bucket,p_prev_from at time zone p_tz), (p_prev_to at time zone p_tz)-interval '1 second', v_step) g
  ), sb as (
    select per, date_trunc(p_bucket, created_at at time zone p_tz) b, sum(total) rev, count(*) cnt from s group by 1,2
  ), wd as (
    select extract(isodow from created_at at time zone p_tz)::int d, sum(total) rev, count(*) cnt from s where per='cur' group by 1
  ), hr as (
    select extract(hour from created_at at time zone p_tz)::int h, sum(total) rev, count(*) cnt from s where per='cur' group by 1
  ), cash as (
    select x.started_at, b.name branch, x.open_cash, x.open_cash_expected
    from public.sales_shifts x left join public.sales_branches b on b.id=x.branch_id
    where x.started_at>=p_from and x.started_at<p_to and (p_branch_id is null or x.branch_id=p_branch_id) and not public.is_test_branch(x.branch_id)
      and x.open_cash is not null and x.open_cash_expected is not null and x.open_cash<>x.open_cash_expected
  ), tests as (
    select r.product_id, p.name, count(*) cnt, round(avg(r.score*100.0/r.total)) pct
    from public.guide_test_results r left join public.products p on p.id=r.product_id
    where r.created_at>=p_from and r.created_at<p_to group by 1,2
  )
  select jsonb_build_object(
    'cur',(select o from per_obj where per='cur'),
    'prev',(select o from per_obj where per='prev'),
    'items',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'cat',cat,'qty',coalesce(qty,0),'rev',coalesce(rev,0),'cost',coalesce(cost,0),'pqty',coalesce(pqty,0),'prev',coalesce(prev,0)) order by coalesce(rev,0) desc),'[]') from items),
    'cats',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'rev',coalesce(rev,0),'prev',coalesce(prev,0)) order by coalesce(rev,0) desc),'[]') from cats),
    'branches',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'rev',coalesce(rev,0),'cnt',cnt,'prev',coalesce(prev,0),'pcnt',pcnt) order by coalesce(rev,0) desc),'[]') from br),
    'employees',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'rev',coalesce(rev,0),'cnt',cnt,'prev',coalesce(prev,0),'pcnt',pcnt) order by coalesce(rev,0) desc),'[]') from em),
    'payments',(select coalesce(jsonb_agg(jsonb_build_object('method',m,'amt',coalesce(amt,0),'prev',coalesce(prev,0)) order by coalesce(amt,0) desc),'[]') from pay),
    'series',(select coalesce(jsonb_agg(jsonb_build_object('b',to_char(cb.b,'YYYY-MM-DD"T"HH24:MI'),'rev',coalesce(x.rev,0),'cnt',coalesce(x.cnt,0)) order by cb.b),'[]') from cur_b cb left join sb x on x.per='cur' and x.b=cb.b),
    'prevSeries',(select coalesce(jsonb_agg(jsonb_build_object('b',to_char(pb.b,'YYYY-MM-DD"T"HH24:MI'),'rev',coalesce(x.rev,0),'cnt',coalesce(x.cnt,0)) order by pb.b),'[]') from prev_b pb left join sb x on x.per='prev' and x.b=pb.b),
    'weekdays',(select coalesce(jsonb_agg(jsonb_build_object('d',d,'rev',rev,'cnt',cnt) order by d),'[]') from wd),
    'hours',(select coalesce(jsonb_agg(jsonb_build_object('h',h,'rev',rev,'cnt',cnt) order by h),'[]') from hr),
    'cashIssues',(select coalesce(jsonb_agg(jsonb_build_object('at',started_at,'branch',branch,'actual',open_cash,'expected',open_cash_expected) order by started_at),'[]') from cash),
    'tests',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'cnt',cnt,'pct',pct) order by pct),'[]') from tests),
    'pickups',(select jsonb_build_object('count',count(*),'sum',coalesce(sum(total),0),
        'overdue',count(*) filter (where created_at<now()-interval '2 days'),'overdueSum',coalesce(sum(total) filter (where created_at<now()-interval '2 days'),0))
      from public.pickup_orders where status='pending' and (p_branch_id is null or branch_id=p_branch_id) and not public.is_test_branch(branch_id)),
    'debts',(select coalesce(sum(d.amount),0) from public.customer_debts d join public.sales x on x.id=d.sale_id where d.paid_at is null and x.status='completed' and not public.is_test_branch(x.branch_id))
  ) into v;
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_summary(p_from timestamp with time zone, p_to timestamp with time zone, p_prev_from timestamp with time zone, p_branch_id bigint DEFAULT NULL::bigint, p_bucket text DEFAULT 'day'::text, p_tz text DEFAULT 'Europe/Moscow'::text)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select public.admin_period_summary(p_from,p_to,p_prev_from,p_from,p_branch_id,p_bucket,p_tz);
$function$;

CREATE OR REPLACE FUNCTION public.announcement_change_note(p_source text, p_key text, p_name text, p_kind text, p_old numeric DEFAULT NULL::numeric, p_new numeric DEFAULT NULL::numeric)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_opposite text;
begin
  if p_kind in ('edit','price','on','off') and exists(select 1 from announcement_changes where status='pending' and source=p_source and item_key=p_key and kind='new') then
    update announcement_changes set item_name=p_name, new_price=coalesce(p_new,new_price), updated_at=now()
      where status='pending' and source=p_source and item_key=p_key and kind='new';
    if p_kind='off' then
      update announcement_changes set status='skipped', updated_at=now()
        where status='pending' and source=p_source and item_key=p_key and kind='new';
    end if;
    return;
  end if;
  if p_kind in ('on','off') then
    v_opposite := case p_kind when 'on' then 'off' else 'on' end;
    if exists(select 1 from announcement_changes where status='pending' and source=p_source and item_key=p_key and kind=v_opposite) then
      update announcement_changes set status='skipped', updated_at=now()
        where status='pending' and source=p_source and item_key=p_key and kind=v_opposite;
      return;
    end if;
  end if;
  insert into announcement_changes(source,item_key,item_name,kind,old_price,new_price)
    values(p_source,p_key,p_name,p_kind,p_old,p_new)
  on conflict (source,item_key,kind) where status='pending'
    do update set item_name=excluded.item_name, new_price=excluded.new_price, updated_at=now();
  if p_kind='price' then
    update announcement_changes set status='skipped', updated_at=now()
      where status='pending' and source=p_source and item_key=p_key and kind='price' and old_price is not distinct from new_price;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.announcement_mark_read(p_announcement_id bigint, p_shift_id bigint, p_person_id bigint)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not exists(select 1 from public.sales_shift_employees se join public.sales_employees e on e.id=se.employee_id
                join public.sales_shifts s on s.id=se.shift_id
                where se.shift_id=p_shift_id and e.person_id=p_person_id and s.status='open') then
    raise exception 'Смена закрыта или сотрудник не участвует в смене'; end if;
  insert into public.announcement_reads(announcement_id,person_id,shift_id) values(p_announcement_id,p_person_id,p_shift_id)
  on conflict(announcement_id,person_id) do nothing;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.announcement_publish_draft(p_title text, p_body text, p_ids bigint[], p_skip bigint[] DEFAULT '{}'::bigint[])
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if not public.is_admin() then raise exception 'Только для администратора'; end if;
  if coalesce(trim(p_title),'')='' then raise exception 'Нужен заголовок'; end if;
  insert into announcements(title, body) values(trim(p_title), nullif(trim(p_body),'')) returning id into v_id;
  update announcement_changes set status='published', announcement_id=v_id, updated_at=now()
    where status='pending' and id = any(coalesce(p_ids,'{}'));
  update announcement_changes set status='skipped', updated_at=now()
    where status='pending' and id = any(coalesce(p_skip,'{}'));
  return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.announcement_track_catalog()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    if coalesce(new.is_active,true) then
      perform announcement_change_note('catalog', new.id::text, new.name, 'new', null, new.price);
    end if;
    return null;
  end if;
  if new.is_active is distinct from old.is_active then
    perform announcement_change_note('catalog', new.id::text, new.name, case when coalesce(new.is_active,true) then 'on' else 'off' end, null, new.price);
  end if;
  if new.price is distinct from old.price and coalesce(new.is_active,true) then
    perform announcement_change_note('catalog', new.id::text, new.name, 'price', old.price, new.price);
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.announcement_track_products()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    perform announcement_change_note('guide', new.id::text, new.name, 'new');
  elsif new.name is distinct from old.name or new.description is distinct from old.description
     or new.category is distinct from old.category or new.sku is distinct from old.sku then
    perform announcement_change_note('guide', new.id::text, new.name, 'edit');
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.customer_debts_from_payment()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_customer uuid;
begin
  if new.payment_method<>'bank_account' then return new; end if;
  select loyalty_customer_id into v_customer from public.sales where id=new.sale_id;
  if v_customer is null then return new; end if;
  insert into public.customer_debts(sale_id,customer_id,amount) values(new.sale_id,v_customer,new.amount)
  on conflict(sale_id) do update set amount=public.customer_debts.amount+excluded.amount;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.debts_list(p_include_paid boolean DEFAULT false)
 RETURNS TABLE(debt_id bigint, sale_id bigint, order_number bigint, sale_created_at timestamp with time zone, branch_name text, employee_name text, customer_id uuid, customer_name text, customer_phone text, amount numeric, sale_total numeric, paid_at timestamp with time zone, items text)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select d.id, s.id, s.order_number, s.created_at, b.name, e.name, c.id, c.name, c.phone, d.amount, s.total, d.paid_at,
    (select string_agg(i.item_name||' × '||trim(to_char(i.quantity,'FM999999990.###')),', ' order by i.id) from public.sale_items i where i.sale_id=s.id)
  from public.customer_debts d
  join public.sales s on s.id=d.sale_id
  join public.loyalty_customers c on c.id=d.customer_id
  left join public.sales_branches b on b.id=s.branch_id
  left join public.sales_employees e on e.id=s.employee_id
  where s.status='completed' and (p_include_paid or d.paid_at is null)
  order by c.name, s.created_at;
$function$;

CREATE OR REPLACE FUNCTION public.debts_list_v2(p_include_paid boolean DEFAULT false, p_branch_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(debt_id bigint, sale_id bigint, order_number bigint, sale_created_at timestamp with time zone, branch_id bigint, branch_name text, employee_name text, customer_id uuid, customer_name text, customer_phone text, amount numeric, sale_total numeric, paid_at timestamp with time zone, items text)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select d.id, s.id, s.order_number, s.created_at, s.branch_id, b.name, e.name, c.id, c.name, c.phone, d.amount, s.total, d.paid_at,
    (select string_agg(i.item_name||' × '||trim(to_char(i.quantity,'FM999999990.###')),', ' order by i.id) from public.sale_items i where i.sale_id=s.id)
  from public.customer_debts d
  join public.sales s on s.id=d.sale_id
  join public.loyalty_customers c on c.id=d.customer_id
  left join public.sales_branches b on b.id=s.branch_id
  left join public.sales_employees e on e.id=s.employee_id
  where s.status='completed' and (p_include_paid or d.paid_at is null)
    and (p_branch_id is null or s.branch_id=p_branch_id)
  order by c.name, s.created_at;
$function$;

CREATE OR REPLACE FUNCTION public.debts_mark_paid(p_debt_ids bigint[])
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update public.customer_debts set paid_at=now() where id=any(p_debt_ids) and paid_at is null;
  get diagnostics v_count=row_count; return v_count;
end $function$;

CREATE OR REPLACE FUNCTION public.debts_mark_unpaid(p_debt_ids bigint[])
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  if not public.is_admin() then raise exception 'Вернуть в долг может только администратор'; end if;
  update public.customer_debts set paid_at=null where id=any(p_debt_ids) and paid_at is not null;
  get diagnostics v_count=row_count; return v_count;
end $function$;
set check_function_bodies = off;
CREATE OR REPLACE FUNCTION public.loyalty_add_purchase(p_name text, p_phone text, p_amount numeric, p_comment text DEFAULT NULL::text)
 RETURNS TABLE(customer_id uuid, customer_name text, customer_phone text, points_added numeric, available_at timestamp with time zone)
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_customer public.loyalty_customers%rowtype;
  v_points numeric(12,2);
  v_available timestamptz;
  v_order_count bigint;
  v_rule public.loyalty_gift_rules%rowtype;
begin
  if nullif(trim(p_name),'') is null then raise exception 'Введите имя клиента'; end if;
  if nullif(trim(p_phone),'') is null then raise exception 'Введите номер клиента'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Сумма покупки должна быть больше 0'; end if;
  v_points := round(p_amount * 0.05, 2);
  v_available := now() + interval '24 hours';
  if length(regexp_replace(trim(p_phone),'[^0-9]','','g')) < 4 then
    raise exception 'Номер клиента должен содержать минимум 4 цифры';
  end if;
  insert into public.loyalty_customers(name, phone, comment)
  values(trim(p_name), regexp_replace(trim(p_phone),'[^0-9]','','g'), nullif(trim(coalesce(p_comment,'')),''))
  on conflict(phone) do update
    set name = excluded.name,
        comment = case when excluded.comment is not null then excluded.comment else public.loyalty_customers.comment end,
        updated_at = now()
  returning * into v_customer;
  insert into public.loyalty_transactions(customer_id, transaction_type, order_amount, points, comment, available_at)
  values(v_customer.id, 'purchase', p_amount, v_points, nullif(trim(coalesce(p_comment,'')),''), v_available);
  select count(*) into v_order_count from public.loyalty_transactions t
  where t.customer_id = v_customer.id and t.transaction_type = 'purchase';
  for v_rule in select * from public.loyalty_gift_rules where order_count = v_order_count loop
    if not exists (select 1 from public.loyalty_transactions t where t.customer_id = v_customer.id and t.transaction_type = 'gift' and t.gift_rule_id = v_rule.id) then
      insert into public.loyalty_transactions(customer_id, transaction_type, order_amount, points, comment, available_at, gift_rule_id)
      values(v_customer.id, 'gift', 0, 0, 'Подарок за ' || v_rule.order_count || ' заказов: ' || v_rule.gift_name, now(), v_rule.id);
    end if;
  end loop;
  return query select v_customer.id, v_customer.name, v_customer.phone, v_points, v_available;
end;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_admin_adjust_points(p_customer_id uuid, p_points numeric, p_comment text DEFAULT NULL::text)
 RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_balance numeric; v_new numeric;
begin
  if not public.is_admin() then raise exception 'Требуется вход администратора'; end if;
  if p_points is null then raise exception 'Укажите изменение баллов'; end if;
  perform 1 from public.loyalty_customers where id=p_customer_id for update;
  if not found then raise exception 'Клиент не найден'; end if;
  select coalesce(sum(t.points),0) into v_balance from public.loyalty_transactions t
  where t.customer_id=p_customer_id and t.available_at <= now();
  v_new := v_balance + p_points;
  if v_new < 0 then raise exception 'Баланс не может быть отрицательным'; end if;
  insert into public.loyalty_transactions(customer_id, transaction_type, order_amount, points, comment, available_at)
  values(p_customer_id, 'adjustment', 0, p_points, nullif(trim(coalesce(p_comment,'')),''), now());
  return v_new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_admin_update_customer(p_customer_id uuid, p_name text, p_phone text, p_comment text)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Требуется вход администратора'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'Имя клиента не может быть пустым'; end if;
  if nullif(trim(p_phone),'') is null then raise exception 'Номер клиента не может быть пустым'; end if;
  update public.loyalty_customers
  set name=trim(p_name), phone=regexp_replace(trim(p_phone),'[^0-9]','','g'), comment=nullif(trim(coalesce(p_comment,'')),''), updated_at=now()
  where id=p_customer_id;
  if not found then raise exception 'Клиент не найден'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_find_customers(p_query text)
 RETURNS TABLE(customer_id uuid, customer_name text, customer_phone text, balance numeric, order_count bigint, customer_comment text, pending_points numeric)
 LANGUAGE sql SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.phone,
    coalesce(sum(case when t.available_at <= now() then t.points else 0 end),0)::numeric as balance,
    count(t.id) filter (where t.transaction_type='purchase')::bigint as order_count,
    c.comment,
    coalesce(sum(case when t.available_at > now() then t.points else 0 end),0)::numeric as pending_points
  from public.loyalty_customers c
  left join public.loyalty_transactions t on t.customer_id=c.id
  where length(regexp_replace(coalesce(p_query,''),'[^0-9]','','g')) >= 4 and c.phone like '%' || right(regexp_replace(coalesce(p_query,''),'[^0-9]','','g'),4)
  group by c.id
  order by c.name;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_get_customer(p_customer_id uuid)
 RETURNS TABLE(customer_id uuid, customer_name text, customer_phone text, balance numeric, order_count bigint, customer_comment text, pending_points numeric)
 LANGUAGE sql SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.phone,
    coalesce(sum(case when t.available_at <= now() then t.points else 0 end),0)::numeric,
    count(t.id) filter (where t.transaction_type='purchase')::bigint,
    c.comment,
    coalesce(sum(case when t.available_at > now() then t.points else 0 end),0)::numeric
  from public.loyalty_customers c
  left join public.loyalty_transactions t on t.customer_id=c.id
  where c.id=p_customer_id
  group by c.id;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_get_history(p_customer_id uuid)
 RETURNS TABLE(customer_name text, customer_phone text, transaction_id bigint, transaction_type text, order_amount numeric, points numeric, comment text, available_at timestamp with time zone, created_at timestamp with time zone, created_by_employee text)
 LANGUAGE sql SECURITY DEFINER SET search_path TO 'public'
AS $function$
    SELECT c.name, c.phone, t.id,
        CASE t.transaction_type
            WHEN 'purchase' THEN 'Покупка / начисление 5%'
            WHEN 'redeem' THEN 'Списание баллов'
            WHEN 'adjustment' THEN 'Корректировка баллов'
            WHEN 'gift' THEN '🎁 Подарок'
            ELSE t.transaction_type
        END,
        t.order_amount, t.points, t.comment, t.available_at, t.created_at,
        COALESCE(sp.name, 'Не указан')
    FROM public.loyalty_transactions t
    JOIN public.loyalty_customers c ON c.id = t.customer_id
    LEFT JOIN public.sales_people sp ON sp.id = c.created_by_employee_id
    WHERE t.customer_id = p_customer_id
    ORDER BY t.created_at DESC;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_redeem(p_customer_id uuid, p_order_amount numeric, p_points numeric, p_comment text DEFAULT NULL::text)
 RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_balance numeric; v_limit numeric;
begin
  if p_order_amount is null or p_order_amount <= 0 then raise exception 'Сумма заказа должна быть больше 0'; end if;
  if p_points is null or p_points <= 0 then raise exception 'Количество баллов должно быть больше 0'; end if;
  v_limit := round(p_order_amount * 0.30, 2);
  if p_points > v_limit then raise exception 'Можно списать не более % баллов', v_limit; end if;
  perform 1 from public.loyalty_customers where id=p_customer_id for update;
  if not found then raise exception 'Клиент не найден'; end if;
  select coalesce(sum(t.points),0) into v_balance from public.loyalty_transactions t
  where t.customer_id=p_customer_id and t.available_at <= now();
  if p_points > v_balance then raise exception 'Недостаточно доступных баллов. Доступно: %', v_balance; end if;
  insert into public.loyalty_transactions(customer_id, transaction_type, order_amount, points, comment, available_at)
  values(p_customer_id, 'redeem', p_order_amount, -p_points, nullif(trim(coalesce(p_comment,'')),''), now());
  return v_balance - p_points;
end;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_register_customer(p_name text, p_phone text, p_comment text DEFAULT NULL::text)
 RETURNS TABLE(customer_id uuid, customer_name text, customer_phone text)
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_customer public.loyalty_customers%rowtype;
begin
  if nullif(trim(p_name),'') is null then raise exception 'Введите имя клиента'; end if;
  if nullif(trim(p_phone),'') is null then raise exception 'Введите номер клиента'; end if;
  if length(regexp_replace(trim(p_phone),'[^0-9]','','g')) < 4 then raise exception 'Номер клиента должен содержать минимум 4 цифры'; end if;
  insert into public.loyalty_customers(name,phone,comment)
  values(trim(p_name),regexp_replace(trim(p_phone),'[^0-9]','','g'),nullif(trim(coalesce(p_comment,'')),''))
  on conflict(phone) do update set name=excluded.name, comment=coalesce(excluded.comment,public.loyalty_customers.comment), updated_at=now()
  returning * into v_customer;
  return query select v_customer.id,v_customer.name,v_customer.phone;
end;
$function$;

CREATE OR REPLACE FUNCTION public.loyalty_register_customer(p_name text, p_phone text, p_comment text DEFAULT NULL::text, p_created_by_employee_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(customer_id uuid, customer_name text, customer_phone text)
 LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_customer public.loyalty_customers%rowtype;
BEGIN
  IF nullif(trim(p_name),'') IS NULL THEN RAISE EXCEPTION 'Введите имя клиента'; END IF;
  IF nullif(trim(p_phone),'') IS NULL THEN RAISE EXCEPTION 'Введите номер клиента'; END IF;
  IF length(regexp_replace(trim(p_phone),'[^0-9]','','g')) < 4 THEN RAISE EXCEPTION 'Номер клиента должен содержать минимум 4 цифры'; END IF;
  INSERT INTO public.loyalty_customers(name, phone, comment, created_by_employee_id)
  VALUES(trim(p_name), regexp_replace(trim(p_phone),'[^0-9]','','g'), nullif(trim(coalesce(p_comment,'')),''), p_created_by_employee_id)
  ON CONFLICT(phone) DO UPDATE SET
    name = excluded.name,
    comment = coalesce(excluded.comment, public.loyalty_customers.comment),
    created_by_employee_id = coalesce(excluded.created_by_employee_id, public.loyalty_customers.created_by_employee_id)
  RETURNING * INTO v_customer;
  RETURN QUERY SELECT v_customer.id, v_customer.name, v_customer.phone;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pickup_list(p_branch_id bigint DEFAULT NULL::bigint, p_include_closed boolean DEFAULT false)
 RETURNS TABLE(id bigint, branch_id bigint, branch_name text, order_number bigint, items jsonb, gross_total numeric, discount_percent numeric, total numeric, customer_id uuid, customer_name text, customer_phone text, client_name text, client_phone text, comment text, employee_name text, status text, created_at timestamp with time zone, paid_at timestamp with time zone, cancelled_at timestamp with time zone, cancel_reason text)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select o.id,o.branch_id,b.name,o.order_number,o.items,o.gross_total,o.discount_percent,o.total,o.customer_id,c.name,c.phone,
    o.client_name,o.client_phone,o.comment,coalesce(p.name,e.name),o.status,o.created_at,o.paid_at,o.cancelled_at,o.cancel_reason
  from public.pickup_orders o
  left join public.sales_branches b on b.id=o.branch_id
  left join public.loyalty_customers c on c.id=o.customer_id
  left join public.sales_employees e on e.id=o.employee_id
  left join public.sales_people p on p.id=e.person_id
  where (p_branch_id is null or o.branch_id=p_branch_id)
    and (o.status='pending' or (p_include_closed and coalesce(o.paid_at,o.cancelled_at)>now()-interval '30 days'))
  order by o.created_at;
$function$;

CREATE OR REPLACE FUNCTION public.pickup_list_v2(p_branch_id bigint DEFAULT NULL::bigint, p_include_closed boolean DEFAULT false)
 RETURNS TABLE(id bigint, branch_id bigint, branch_name text, order_number bigint, items jsonb, gross_total numeric, discount_percent numeric, total numeric, customer_id uuid, customer_name text, customer_phone text, client_name text, client_phone text, comment text, employee_name text, status text, created_at timestamp with time zone, paid_at timestamp with time zone, cancelled_at timestamp with time zone, cancel_reason text, client_order_ref text)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select l.*, o.client_order_ref from public.pickup_list(p_branch_id,p_include_closed) l join public.pickup_orders o on o.id=l.id order by l.created_at;
$function$;

CREATE OR REPLACE FUNCTION public.rep_esc(x text) RETURNS text LANGUAGE sql IMMUTABLE
AS $function$ select replace(replace(replace(x,'&','&amp;'),'<','&lt;'),'>','&gt;') $function$;
CREATE OR REPLACE FUNCTION public.rep_money(x numeric) RETURNS text LANGUAGE sql IMMUTABLE
AS $function$ select replace(to_char(round(coalesce(x,0)),'FM999,999,999,990'),',',' ')||' ₽' $function$;
CREATE OR REPLACE FUNCTION public.rep_pct(cur numeric, prev numeric) RETURNS text LANGUAGE sql IMMUTABLE
AS $function$
  select case when coalesce(prev,0)=0 then '' else
    ' ('||case when cur>=prev then '+' else '−' end||abs(round((cur-prev)*100/prev))||'%)' end
$function$;
CREATE OR REPLACE FUNCTION public.rep_person(p_employee_id bigint) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce(pp.name,e.name,'?') from public.sales_employees e left join public.sales_people pp on pp.id=e.person_id where e.id=p_employee_id
$function$;

CREATE OR REPLACE FUNCTION public.report_admin_set_cells(p_sheet_id bigint, p_cells jsonb, p_months jsonb DEFAULT NULL::jsonb)
 RETURNS timestamp with time zone LANGUAGE plpgsql SET search_path TO 'public'
AS $function$
declare v_data jsonb; r text; cols jsonb; k text; cell jsonb; v_row jsonb; v_now timestamptz:=now();
begin
  select data into v_data from public.report_sheets where id=p_sheet_id for update;
  if not found then raise exception 'Лист не найден'; end if;
  for r,cols in select * from jsonb_each(p_cells) loop
    v_row:=coalesce(v_data->'rows'->r,'{}'::jsonb);
    for k,cell in select * from jsonb_each(cols) loop
      if cell is null or jsonb_typeof(cell)='null' then v_row:=v_row-k; else v_row:=v_row||jsonb_build_object(k,cell); end if;
    end loop;
    v_data:=jsonb_set(v_data,array['rows',r],v_row,true);
  end loop;
  update public.report_sheets set data=v_data, months=coalesce(p_months,months), updated_at=v_now where id=p_sheet_id;
  return v_now;
end $function$;

CREATE OR REPLACE FUNCTION public.report_branch_month(p_shift_id bigint)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_branch bigint; v_sheet public.report_sheets; v_month jsonb; v_rows jsonb; v_key text;
begin
  select branch_id into v_branch from public.sales_shifts where id=p_shift_id and status='open';
  if not found then raise exception 'Смена не найдена или уже закрыта'; end if;
  select * into v_sheet from public.report_sheets where branch_id=v_branch order by sort_order limit 1;
  if not found then return null; end if;
  v_key:=to_char(now() at time zone 'Europe/Moscow','YYYY-MM');
  select m into v_month from jsonb_array_elements(v_sheet.months) m where m->>'m'=v_key limit 1;
  if v_month is null then
    select m into v_month from jsonb_array_elements(v_sheet.months) m where m->>'m'<=v_key order by m->>'m' desc limit 1;
  end if;
  if v_month is null then return null; end if;
  select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) into v_rows
    from jsonb_each(v_sheet.data->'rows') as r(k,v)
    where k::int between (v_month->>'from')::int and (v_month->>'to')::int;
  return jsonb_build_object('title',v_sheet.title,'month',v_month->>'m','from',(v_month->>'from')::int,'to',(v_month->>'to')::int,
    'data',jsonb_build_object('ncols',v_sheet.data->'ncols','cols',v_sheet.data->'cols','styles',v_sheet.data->'styles',
      'merges',v_sheet.data->'merges','heights',v_sheet.data->'heights','rows',v_rows),
    'updated_at',v_sheet.updated_at);
end $function$;

CREATE OR REPLACE FUNCTION public.report_col_name(n integer) RETURNS text LANGUAGE plpgsql IMMUTABLE
AS $function$
declare s text:=''; m int;
begin while n>0 loop m:=(n-1)%26; s:=chr(65+m)||s; n:=(n-m-1)/26; end loop; return s; end $function$;

CREATE OR REPLACE FUNCTION public.report_col_num(s text) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path TO 'public'
AS $function$
  select sum((ascii(substr(s,i,1))-64)*power(26,length(s)-i))::int from generate_series(1,length(s)) i
$function$;

CREATE OR REPLACE FUNCTION public.report_day_row(p_branch_id bigint, p_day date, OUT sheet_id bigint, OUT row_no integer, OUT m_from integer, OUT m_to integer)
 RETURNS record LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_sheet public.report_sheets; v_month jsonb; v_serial int:=p_day-date '1899-12-30';
begin
  select * into v_sheet from public.report_sheets s where s.branch_id=p_branch_id order by s.sort_order limit 1;
  if not found then raise exception 'Для этого филиала нет листа в общем отчете'; end if;
  select m into v_month from jsonb_array_elements(v_sheet.months) m where m->>'m'=to_char(p_day,'YYYY-MM') limit 1;
  if v_month is null then raise exception 'В общем отчете нет месяца %', to_char(p_day,'MM.YYYY'); end if;
  sheet_id:=v_sheet.id; m_from:=(v_month->>'from')::int; m_to:=(v_month->>'to')::int;
  select k::int into row_no from jsonb_each(v_sheet.data->'rows') as r(k,v)
   where k::int between m_from and m_to and v->'A'->>'v'=v_serial::text limit 1;
  if row_no is null then raise exception 'В общем отчете нет строки на %', to_char(p_day,'DD.MM.YYYY'); end if;
end $function$;

CREATE OR REPLACE FUNCTION public.report_fill_shift(p_shift_id bigint, p_mode text)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; d record; v_shifts bigint[]; v_names text; v_vals jsonb;
begin
  if p_mode not in ('auto','manual') then raise exception 'Неизвестный способ заполнения'; end if;
  select * into c from public.report_shift_ctx(p_shift_id);
  if public.is_test_branch(c.branch_id) then raise exception 'Тестовый филиал в общий отчет не попадает'; end if;
  select * into d from public.report_day_row(c.branch_id, c.day);
  insert into public.report_fills(shift_id,branch_id,day,mode,sheet_id,row_no)
    values (p_shift_id,c.branch_id,c.day,p_mode,d.sheet_id,d.row_no)
    on conflict (shift_id) do update set mode=excluded.mode, sheet_id=excluded.sheet_id, row_no=excluded.row_no, updated_at=now();
  if p_mode='auto' then
    select array_agg(id) into v_shifts from public.sales_shifts
     where branch_id=c.branch_id and (started_at at time zone 'Europe/Moscow')::date=c.day;
    select string_agg(nm,'/' order by first_at) into v_names from (
      select coalesce(nullif(btrim(p.name),''),e.name) nm, min(se.created_at) first_at
        from public.sales_shift_employees se join public.sales_employees e on e.id=se.employee_id
        left join public.sales_people p on p.id=e.person_id
       where se.shift_id=any(v_shifts) group by 1) x;
    with v as (select id,total from public.sales where shift_id=any(v_shifts) and status='completed' and payment_status<>'unpaid'),
         pay as (select p.payment_method m, sum(p.amount) a from public.sale_payments p join v on v.id=p.sale_id group by 1)
    select jsonb_build_object(
      'C', v_names,
      'D', (select coalesce(sum(total),0) from v),
      'G', coalesce((select a from pay where m='card'),0),
      'H', coalesce((select a from pay where m='qr'),0),
      'I', coalesce((select a from pay where m='link'),0),
      'J', coalesce((select a from pay where m='transfer'),0),
      'K', coalesce((select a from pay where m='bank_account'),0),
      'L', (select count(*) from v),
      'M', (select coalesce(sum(amount),0) from public.sales_returns where shift_id=any(v_shifts)),
      'Q', (select coalesce(sum(i.quantity),0) from public.sale_items i join v on v.id=i.sale_id
             where i.item_type='service' and i.item_name ilike '%ретуш%')) into v_vals;
    perform public.report_put_row(d.sheet_id, d.row_no, v_vals);
    perform public.report_recalc_total(d.sheet_id, d.m_to);
  end if;
  return public.report_staff_view(p_shift_id);
end $function$;

CREATE OR REPLACE FUNCTION public.report_import_apply()
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare r record; j jsonb; v_rows jsonb; v_id bigint; v_out jsonb:='[]'::jsonb; v_cells int;
begin
  for r in select sheet_no, string_agg(body,'' order by part) txt from public.report_import group by sheet_no order by sheet_no loop
    j:=r.txt::jsonb;
    with allc as (
      select public.report_col_name(e.i::int)||rw.key addr, jsonb_build_object('v',e.val) cell
        from jsonb_each(j->'rows') rw, jsonb_array_elements(rw.value) with ordinality e(val,i) where e.val<>'null'::jsonb
      union all
      select f.key, jsonb_strip_nulls(jsonb_build_object('f',f.value->0,'v',f.value->1)) from jsonb_each(j->'fm') f
      union all
      select public.report_col_name(c)||rr, jsonb_build_object('s',st.key::int)
        from jsonb_each(j->'st') st, jsonb_array_elements_text(st.value) a,
             lateral (select regexp_match(a,'^([A-Z]+)([0-9]+)(?::([A-Z]+)([0-9]+))?$') m) p,
             generate_series(public.report_col_num(p.m[1]), public.report_col_num(coalesce(p.m[3],p.m[1]))) c,
             generate_series(p.m[2]::int, coalesce(p.m[4],p.m[2])::int) rr),
    merged as (
      select x.addr, jsonb_object_agg(kv.key,kv.value) cell from allc x, jsonb_each(x.cell) kv group by x.addr),
    byrow as (
      select substring(addr from '[0-9]+$') rn, jsonb_object_agg(substring(addr from '^[A-Z]+'), cell) rowobj from merged group by 1)
    select coalesce(jsonb_object_agg(rn,rowobj),'{}'::jsonb), (select count(*) from merged) into v_rows, v_cells from byrow;
    select id into v_id from public.report_sheets where lower(trim(title))=lower(trim(j->>'t')) limit 1;
    if v_id is null then
      insert into public.report_sheets(sort_order,title,branch_id,data,months)
      values ((j->>'o')::int, j->>'t', nullif(j->>'b','')::bigint, (j->'meta')||jsonb_build_object('rows',v_rows), coalesce(j->'months','[]'::jsonb))
      returning id into v_id;
    else
      update public.report_sheets set sort_order=(j->>'o')::int, branch_id=nullif(j->>'b','')::bigint,
        data=(j->'meta')||jsonb_build_object('rows',v_rows), months=coalesce(j->'months','[]'::jsonb), updated_at=now() where id=v_id;
    end if;
    v_out:=v_out||jsonb_build_object('title',j->>'t','cells',v_cells);
  end loop;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.report_past_rows(p_sheet_id bigint, p_from integer, p_day_row integer)
 RETURNS integer[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(k::int order by k::int),array[]::int[]) from public.report_sheets s, jsonb_each(s.data->'rows') as r(k,v)
   where s.id=p_sheet_id and k::int>=p_from and k::int<p_day_row and jsonb_typeof(v->'A'->'v')='number'
$function$;

CREATE OR REPLACE FUNCTION public.report_put_row(p_sheet_id bigint, p_row integer, p_vals jsonb)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_row jsonb; v_cell jsonb; k text; val jsonb;
begin
  select coalesce(data->'rows'->(p_row::text),'{}'::jsonb) into v_row from public.report_sheets where id=p_sheet_id for update;
  for k,val in select * from jsonb_each(p_vals) loop
    v_cell:=coalesce(v_row->k,'{}'::jsonb)-'v'-'f';
    if val is not null and jsonb_typeof(val)<>'null' then v_cell:=v_cell||jsonb_build_object('v',val); end if;
    if v_cell='{}'::jsonb then v_row:=v_row-k; else v_row:=v_row||jsonb_build_object(k,v_cell); end if;
  end loop;
  update public.report_sheets set data=jsonb_set(data,array['rows',p_row::text],v_row,true), updated_at=now() where id=p_sheet_id;
end $function$;

CREATE OR REPLACE FUNCTION public.report_recalc_total(p_sheet_id bigint, p_row integer)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_data jsonb; k text; c jsonb; m text[]; s numeric; vals jsonb:='{}'::jsonb;
begin
  select data into v_data from public.report_sheets where id=p_sheet_id;
  for k,c in select * from jsonb_each(coalesce(v_data->'rows'->(p_row::text),'{}'::jsonb)) loop
    m:=regexp_match(coalesce(c->>'f',''),'^SUM\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)$');
    if m is null or m[1]<>k or m[3]<>k then continue; end if;
    select coalesce(sum((v->k->>'v')::numeric),0) into s from jsonb_each(v_data->'rows') as r(rk,v)
     where rk::int between m[2]::int and m[4]::int and jsonb_typeof(v->k->'v')='number';
    vals:=vals||jsonb_build_object(k,s);
  end loop;
  if vals='{}'::jsonb then return; end if;
  update public.report_sheets set data=jsonb_set(data,array['rows',p_row::text],
    (select jsonb_object_agg(kk, case when vals ? kk then vv||jsonb_build_object('v',vals->kk) else vv end)
       from jsonb_each(data->'rows'->(p_row::text)) as x(kk,vv)),true)
   where id=p_sheet_id;
end $function$;

CREATE OR REPLACE FUNCTION public.report_shift_ctx(p_shift_id bigint, OUT branch_id bigint, OUT day date)
 RETURNS record LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  select sh.branch_id, (sh.started_at at time zone 'Europe/Moscow')::date into branch_id, day
    from public.sales_shifts sh where sh.id=p_shift_id;
  if not found then raise exception 'Смена не найдена'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.report_staff_cols(p_mode text) RETURNS text[] LANGUAGE sql IMMUTABLE
AS $function$
  select case p_mode when 'auto' then array['E','F','N','O','P','R','S']
                     when 'manual' then array['C','D','E','F','G','H','I','J','K','L','M','N','O','P','Q','R','S']
                     else array[]::text[] end
$function$;

CREATE OR REPLACE FUNCTION public.report_staff_set(p_shift_id bigint, p_col text, p_value jsonb)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; d record; v_mode text; v_data jsonb;
begin
  select * into c from public.report_shift_ctx(p_shift_id);
  select * into d from public.report_day_row(c.branch_id, c.day);
  select mode into v_mode from public.report_fills where shift_id=p_shift_id;
  if v_mode is null then
    select mode into v_mode from public.report_fills where branch_id=c.branch_id and day=c.day order by updated_at desc limit 1;
  end if;
  if v_mode is null then raise exception 'Сначала нажмите «Перенести в общий отчет» или «Заполнить отчет вручную»'; end if;
  if not (p_col = any(public.report_staff_cols(v_mode))) then raise exception 'Эту клетку заполняет касса'; end if;
  if p_value is not null and jsonb_typeof(p_value) not in ('number','string','null') then raise exception 'Неверное значение'; end if;
  if jsonb_typeof(p_value)='string' and length(p_value#>>'{}')>500 then raise exception 'Слишком длинный текст'; end if;
  perform public.report_put_row(d.sheet_id, d.row_no, jsonb_build_object(p_col,p_value));
  perform public.report_recalc_total(d.sheet_id, d.m_to);
  update public.report_fills set updated_at=now() where shift_id=p_shift_id;
  select data into v_data from public.report_sheets where id=d.sheet_id;
  return jsonb_build_object(d.row_no::text, v_data->'rows'->(d.row_no::text), d.m_to::text, v_data->'rows'->(d.m_to::text));
end $function$;

CREATE OR REPLACE FUNCTION public.report_staff_set_past(p_shift_id bigint, p_row integer, p_col text, p_value jsonb)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; d record; v_data jsonb; v_day date; v_shift bigint;
begin
  select * into c from public.report_shift_ctx(p_shift_id);
  if public.is_test_branch(c.branch_id) then raise exception 'Тестовый филиал в общий отчет не попадает'; end if;
  select * into d from public.report_day_row(c.branch_id, c.day);
  if not (p_row = any(public.report_past_rows(d.sheet_id,d.m_from,d.row_no))) then raise exception 'Эту строку менять нельзя'; end if;
  if not (p_col = any(public.report_staff_cols('manual'))) then raise exception 'Эту клетку менять нельзя'; end if;
  if p_value is not null and jsonb_typeof(p_value) not in ('number','string','null') then raise exception 'Неверное значение'; end if;
  if jsonb_typeof(p_value)='string' and length(p_value#>>'{}')>500 then raise exception 'Слишком длинный текст'; end if;
  perform public.report_put_row(d.sheet_id, p_row, jsonb_build_object(p_col,p_value));
  perform public.report_recalc_total(d.sheet_id, d.m_to);
  select data into v_data from public.report_sheets where id=d.sheet_id;
  v_day:=date '1899-12-30'+(v_data->'rows'->(p_row::text)->'A'->>'v')::numeric::int;
  if not exists(select 1 from public.report_fills where branch_id=c.branch_id and day=v_day) then
    select id into v_shift from public.sales_shifts where branch_id=c.branch_id and (started_at at time zone 'Europe/Moscow')::date=v_day order by started_at limit 1;
    if v_shift is not null then
      insert into public.report_fills(shift_id,branch_id,day,mode,sheet_id,row_no) values (v_shift,c.branch_id,v_day,'manual',d.sheet_id,p_row) on conflict (shift_id) do nothing;
    end if;
  else
    update public.report_fills set updated_at=now() where branch_id=c.branch_id and day=v_day;
  end if;
  return jsonb_build_object(p_row::text, v_data->'rows'->(p_row::text), d.m_to::text, v_data->'rows'->(d.m_to::text));
end $function$;

CREATE OR REPLACE FUNCTION public.report_staff_sheets()
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'data',data) order by sort_order,id),'[]'::jsonb)
  from public.report_sheets where staff_visible and branch_id is null;
$function$;

CREATE OR REPLACE FUNCTION public.report_staff_view(p_shift_id bigint)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare c record; d record; v_sheet public.report_sheets; v_rows jsonb; v_mode text;
begin
  select * into c from public.report_shift_ctx(p_shift_id);
  select * into d from public.report_day_row(c.branch_id, c.day);
  select * into v_sheet from public.report_sheets where id=d.sheet_id;
  select mode into v_mode from public.report_fills where shift_id=p_shift_id;
  if v_mode is null then
    select mode into v_mode from public.report_fills where branch_id=c.branch_id and day=c.day order by updated_at desc limit 1;
  end if;
  select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) into v_rows from jsonb_each(v_sheet.data->'rows') as r(k,v)
   where k::int between d.m_from and d.m_to;
  return jsonb_build_object('title',v_sheet.title,'month',to_char(c.day,'YYYY-MM'),'from',d.m_from,'to',d.m_to,'row',d.row_no,
    'mode',v_mode,'cols',to_jsonb(public.report_staff_cols(v_mode)),
    'past',to_jsonb(public.report_past_rows(d.sheet_id,d.m_from,d.row_no)),'past_cols',to_jsonb(public.report_staff_cols('manual')),
    'data',jsonb_build_object('ncols',v_sheet.data->'ncols','cols',v_sheet.data->'cols','styles',v_sheet.data->'styles',
      'merges',v_sheet.data->'merges','heights',v_sheet.data->'heights','rows',v_rows),
    'updated_at',v_sheet.updated_at);
end $function$;
set check_function_bodies = off;
CREATE OR REPLACE FUNCTION public.sales_cancel_pickup(p_pickup_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  update public.pickup_orders set status='cancelled',cancelled_at=now(),cancel_reason=nullif(trim(coalesce(p_reason,'')),'')
  where id=p_pickup_id and status='pending';
  if not found then raise exception 'Заказ не найден или уже закрыт'; end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_close_shift(p_shift_id bigint)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_closed boolean;
begin
  update public.sales_shifts set status = 'closed', ended_at = coalesce(ended_at, now())
   where id = p_shift_id and status = 'open';
  v_closed := found;
  return v_closed;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sales_close_team_shift(p_shift_id bigint, p_employee_id bigint)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_branch_id bigint; v_shift public.sales_shifts%rowtype;
begin
  select branch_id into v_branch_id from public.sales_shifts where id=p_shift_id;
  if not found then raise exception 'Смена не найдена'; end if;
  perform pg_advisory_xact_lock(v_branch_id);
  select * into v_shift from public.sales_shifts where id=p_shift_id for update;
  if not exists(select 1 from public.sales_shift_employees where shift_id=p_shift_id and employee_id=p_employee_id) then
    raise exception 'Кассир не является участником смены';
  end if;
  if v_shift.status<>'open' then return false; end if;
  if exists(select 1 from public.sales_shift_tasks t where t.branch_id=v_branch_id and t.is_active
    and t.task_date=(now() at time zone 'Europe/Moscow')::date
    and not exists(select 1 from public.sales_shift_task_completions c where c.task_id=t.id and c.shift_id=p_shift_id)) then
    raise exception 'Подтвердите выполнение заданий смены';
  end if;
  if public.kassa_cash_check_enabled() and v_shift.close_cash is null then
    raise exception 'Укажите остаток наличных в кассе. Если окна для суммы нет — обновите страницу (Ctrl+F5).';
  end if;
  update public.sales_shifts set status='closed',ended_at=now() where id=p_shift_id;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_complete_person_task(p_task_id bigint, p_shift_id bigint, p_employee_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_person bigint;
begin
  select e.person_id into v_person
  from sales_shift_employees se
  join sales_employees e on e.id = se.employee_id
  join sales_shifts s on s.id = se.shift_id
  where se.shift_id = p_shift_id and se.employee_id = p_employee_id and s.ended_at is null;
  if v_person is null then raise exception 'Смена закрыта или сотрудник не участвует в смене'; end if;
  update sales_person_tasks
     set completed_at = now(), completed_shift_id = p_shift_id, completed_by_employee_id = p_employee_id
   where id = p_task_id and person_id = v_person and completed_at is null and is_active;
  if not found then raise exception 'Задание не найдено или уже выполнено'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_create_sale(p_shift_id bigint, p_employee_id bigint, p_payment_method text, p_comment text, p_items jsonb, p_loyalty_customer_id uuid DEFAULT NULL::uuid, p_loyalty_points numeric DEFAULT 0, p_loyalty_name text DEFAULT NULL::text, p_loyalty_phone text DEFAULT NULL::text, p_loyalty_comment text DEFAULT NULL::text, p_order_number bigint DEFAULT NULL::bigint, p_discount_percent numeric DEFAULT 0, p_payments jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_shift public.sales_shifts%rowtype;
  v_sale_id bigint;
  v_order bigint;
  v_gross numeric(12,2):=0;
  v_discount numeric(12,2):=0;
  v_after_discount numeric(12,2):=0;
  v_total numeric(12,2):=0;
  v_points numeric(12,2):=round(coalesce(p_loyalty_points,0),2);
  v_item jsonb; v_pay jsonb; v_catalog public.sales_catalog%rowtype;
  v_qty numeric(12,3); v_price numeric(12,2); v_line numeric(12,2);
  v_pay_sum numeric(12,2):=0; v_customer_id uuid:=p_loyalty_customer_id;
  v_min bigint;
  v_forced bigint:=nullif(current_setting('polaroid.pickup_order',true),'')::bigint;
begin
  select * into v_shift from public.sales_shifts where id=p_shift_id and (status='open' or current_setting('polaroid.offline_sync',true)='1') for update;
  if not found then raise exception 'Смена не найдена или уже закрыта'; end if;
  if not exists(select 1 from public.sales_shift_employees where shift_id=p_shift_id and employee_id=p_employee_id) then raise exception 'Сотрудник не подключён к этой смене'; end if;
  if p_payment_method not in ('cash','card','qr','link','bank_account','transfer','split') then raise exception 'Выберите способ оплаты'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Добавьте хотя бы одну позицию'; end if;
  if coalesce(p_discount_percent,0)<0 or coalesce(p_discount_percent,0)>100 then raise exception 'Скидка должна быть от 0 до 100%%'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select * into v_catalog from public.sales_catalog where id=(v_item->>'catalog_id')::bigint and is_active=true;
    if not found then raise exception 'Товар или услуга не найдены'; end if;
    v_qty:=coalesce((v_item->>'quantity')::numeric,0); v_price:=coalesce((v_item->>'unit_price')::numeric,v_catalog.price);
    if v_qty<=0 or v_price<0 then raise exception 'Некорректное количество или цена'; end if;
    v_line:=round(v_qty*v_price,2); v_gross:=v_gross+v_line;
  end loop;
  v_discount:=round(v_gross*coalesce(p_discount_percent,0)/100,2);
  v_after_discount:=round(v_gross-v_discount,2);
  if v_points<0 or v_points>round(v_after_discount*0.30,2) then raise exception 'Баллами можно оплатить не более 30%% после скидки'; end if;
  if v_points>0 then
    if v_customer_id is null then raise exception 'Выберите клиента клубной карты'; end if;
    perform public.loyalty_redeem(v_customer_id,v_after_discount,v_points,'Списание баллов при продаже');
  end if;
  v_total:=round(v_after_discount-v_points,2);

  if p_payment_method='split' then
    if jsonb_typeof(p_payments)<>'array' or jsonb_array_length(p_payments)<2 then raise exception 'Для раздельной оплаты добавьте минимум два способа оплаты'; end if;
    for v_pay in select * from jsonb_array_elements(p_payments) loop
      if (v_pay->>'method') not in ('cash','card','qr','link','bank_account','transfer') then raise exception 'Некорректный способ в раздельной оплате'; end if;
      if coalesce((v_pay->>'amount')::numeric,0)<=0 then raise exception 'Сумма каждого способа оплаты должна быть больше 0'; end if;
      v_pay_sum:=v_pay_sum+round((v_pay->>'amount')::numeric,2);
    end loop;
  else
    v_pay_sum:=v_total;
  end if;
  if round(v_pay_sum,2)<>round(v_total,2) then raise exception 'Сумма способов оплаты должна быть ровно %',v_total; end if;

  insert into public.sales_branch_order_counters(branch_id,next_number) values(v_shift.branch_id,1000) on conflict(branch_id) do nothing;
  select next_number into v_min from public.sales_branch_order_counters where branch_id=v_shift.branch_id for update;
  if v_forced is not null and v_forced=p_order_number
     and not exists(select 1 from public.sales s where s.branch_id=v_shift.branch_id and s.order_number=v_forced) then
    v_order:=v_forced;
  else
    select greatest(v_min, coalesce(max(s.order_number)+1,v_min)) into v_min
    from public.sales s where s.branch_id=v_shift.branch_id;
    v_order:=case when p_order_number is null or p_order_number<v_min then v_min else p_order_number end;
    while exists(select 1 from public.sales s where s.branch_id=v_shift.branch_id and s.order_number=v_order)
       or exists(select 1 from public.pickup_orders o where o.branch_id=v_shift.branch_id and o.order_number=v_order and o.status='pending') loop
      v_order:=v_order+1;
    end loop;
  end if;

  if v_customer_id is null and nullif(trim(coalesce(p_loyalty_phone,'')),'') is not null then
    select x.customer_id into v_customer_id from public.loyalty_add_purchase(trim(p_loyalty_name),trim(p_loyalty_phone),v_gross,nullif(trim(coalesce(p_loyalty_comment,'')),'')) x limit 1;
  elsif v_customer_id is not null then
    select x.customer_id into v_customer_id from public.loyalty_customers c cross join lateral public.loyalty_add_purchase(c.name,c.phone,v_gross,nullif(trim(coalesce(p_loyalty_comment,'')),'')) x where c.id=v_customer_id;
  end if;

  insert into public.sales(order_number,shift_id,branch_id,employee_id,payment_method,total,gross_total,discount_percent,discount_amount,loyalty_points_used,loyalty_customer_id,comment,receipt_issued,payment_status,paid_at)
  values(v_order,v_shift.id,v_shift.branch_id,p_employee_id,p_payment_method,v_total,v_gross,coalesce(p_discount_percent,0),v_discount,v_points,v_customer_id,nullif(trim(coalesce(p_comment,'')),''),case when p_payment_method='link' then null else true end,case when p_payment_method='link' then 'pending' else 'paid' end,case when p_payment_method='link' then null else now() end)
  returning id into v_sale_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select * into v_catalog from public.sales_catalog where id=(v_item->>'catalog_id')::bigint;
    v_qty:=(v_item->>'quantity')::numeric; v_price:=(v_item->>'unit_price')::numeric; v_line:=round(v_qty*v_price,2);
    insert into public.sale_items(sale_id,catalog_id,item_type,item_name,quantity,unit_price,line_total,cost_price,cost_total,variant_material_id)
    values(v_sale_id,v_catalog.id,v_catalog.item_type,v_catalog.name,v_qty,v_price,v_line,v_catalog.cost_price,round(coalesce(v_catalog.cost_price,0)*v_qty,2),
      (select m.id from public.stock_materials m where m.id=nullif(v_item->>'variant_material_id','')::bigint and (m.variant_catalog_id=v_catalog.id or exists(select 1 from public.stock_norms n where n.material_id=m.parent_id and n.catalog_id=v_catalog.id and n.active))));
  end loop;
  if p_payment_method='split' then
    for v_pay in select * from jsonb_array_elements(p_payments) loop
      insert into public.sale_payments(sale_id,payment_method,amount) values(v_sale_id,(v_pay->>'method'),round((v_pay->>'amount')::numeric,2));
    end loop;
  else
    insert into public.sale_payments(sale_id,payment_method,amount) values(v_sale_id,p_payment_method,v_total);
  end if;
  update public.sales_branch_order_counters set next_number=greatest(next_number,v_order+1),updated_at=now() where branch_id=v_shift.branch_id;
  return v_order;
end; $function$;

CREATE OR REPLACE FUNCTION public.sales_create_sale_v6(p_client_uid uuid, p_offline_at timestamp with time zone, p_shift_id bigint, p_employee_id bigint, p_payment_method text, p_comment text, p_items jsonb, p_loyalty_customer_id uuid DEFAULT NULL::uuid, p_loyalty_points numeric DEFAULT 0, p_loyalty_name text DEFAULT NULL::text, p_loyalty_phone text DEFAULT NULL::text, p_loyalty_comment text DEFAULT NULL::text, p_order_number bigint DEFAULT NULL::bigint, p_discount_percent numeric DEFAULT 0, p_payments jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare
  v_existing bigint; v_order bigint;
  v_at timestamptz:=case when p_offline_at is null then null else least(greatest(p_offline_at,now()-interval '14 days'),now()) end;
begin
  if p_client_uid is null then raise exception 'Нет идентификатора продажи'; end if;
  perform pg_advisory_xact_lock(hashtext('sale:'||p_client_uid::text));
  select order_number into v_existing from public.sales where client_uid=p_client_uid;
  if found then return v_existing; end if;
  if v_at is not null then perform set_config('polaroid.offline_sync','1',true); end if;
  v_order:=public.sales_create_sale(p_shift_id,p_employee_id,p_payment_method,p_comment,p_items,p_loyalty_customer_id,p_loyalty_points,
    p_loyalty_name,p_loyalty_phone,p_loyalty_comment,p_order_number,p_discount_percent,p_payments);
  perform set_config('polaroid.offline_sync','',true);
  update public.sales s set client_uid=p_client_uid,
    offline_at=v_at,
    created_at=coalesce(v_at,s.created_at),
    paid_at=case when s.paid_at is not null and v_at is not null then v_at else s.paid_at end
  where s.id=(select x.id from public.sales x join public.sales_shifts sh on sh.branch_id=x.branch_id
              where sh.id=p_shift_id and x.order_number=v_order order by x.id desc limit 1);
  return v_order;
end; $function$;

CREATE OR REPLACE FUNCTION public.sales_ensure_employee(p_person_id bigint, p_branch_id bigint)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_person public.sales_people%rowtype; v_employee public.sales_employees%rowtype;
begin
  perform pg_advisory_xact_lock(p_branch_id);
  if not exists(select 1 from public.sales_branches where id=p_branch_id and is_active) then
    raise exception 'Филиал не найден или отключён';
  end if;
  select * into v_person from public.sales_people where id=p_person_id and is_active;
  if not found then raise exception 'Сотрудник не найден или отключён'; end if;
  select * into v_employee from public.sales_employees where person_id=p_person_id and branch_id=p_branch_id for update;
  if not found then
    insert into public.sales_employees(person_id,branch_id,name,is_active)
    values(p_person_id,p_branch_id,v_person.name,true) returning * into v_employee;
  elsif not v_employee.is_active then
    update public.sales_employees set is_active=true where id=v_employee.id returning * into v_employee;
  end if;
  return to_jsonb(v_employee);
end $function$;

CREATE OR REPLACE FUNCTION public.sales_get_shift_context(p_shift_id bigint)
 RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'shiftId',s.id,'branchId',s.branch_id,'branchName',b.name,'status',s.status,'startedAt',s.started_at,
  'participants',coalesce((select jsonb_agg(jsonb_build_object(
    'employeeId',e.id,'personId',e.person_id,'name',coalesce(person.name,e.name),'isLead',p.is_lead,
    'isActive',coalesce(person.is_active,false) and e.is_active) order by e.id)
    from public.sales_shift_employees p join public.sales_employees e on e.id=p.employee_id
    left join public.sales_people person on person.id=e.person_id where p.shift_id=s.id),'[]'::jsonb))
from public.sales_shifts s join public.sales_branches b on b.id=s.branch_id where s.id=p_shift_id;
$function$;

CREATE OR REPLACE FUNCTION public.sales_hold_pickup(p_shift_id bigint, p_employee_id bigint, p_items jsonb, p_discount_percent numeric DEFAULT 0, p_comment text DEFAULT NULL::text, p_order_number bigint DEFAULT NULL::bigint, p_customer_id uuid DEFAULT NULL::uuid, p_client_name text DEFAULT NULL::text, p_client_phone text DEFAULT NULL::text)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_shift public.sales_shifts%rowtype; v_item jsonb; v_cat public.sales_catalog%rowtype;
  v_qty numeric(12,3); v_price numeric(12,2); v_line numeric(12,2); v_gross numeric(12,2):=0; v_total numeric(12,2);
  v_items jsonb:='[]'::jsonb; v_min bigint; v_order bigint;
begin
  select * into v_shift from public.sales_shifts where id=p_shift_id and status='open' for update;
  if not found then raise exception 'Смена не найдена или уже закрыта'; end if;
  if not exists(select 1 from public.sales_shift_employees where shift_id=p_shift_id and employee_id=p_employee_id) then raise exception 'Сотрудник не подключён к этой смене'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Добавьте хотя бы одну позицию'; end if;
  if coalesce(p_discount_percent,0)<0 or coalesce(p_discount_percent,0)>100 then raise exception 'Скидка должна быть от 0 до 100%%'; end if;
  for v_item in select * from jsonb_array_elements(p_items) loop
    select * into v_cat from public.sales_catalog where id=(v_item->>'catalog_id')::bigint and is_active=true;
    if not found then raise exception 'Товар или услуга не найдены'; end if;
    v_qty:=coalesce((v_item->>'quantity')::numeric,0); v_price:=coalesce((v_item->>'unit_price')::numeric,v_cat.price);
    if v_qty<=0 or v_price<0 then raise exception 'Некорректное количество или цена'; end if;
    v_line:=round(v_qty*v_price,2); v_gross:=v_gross+v_line;
    v_items:=v_items||jsonb_build_array(jsonb_build_object('catalog_id',v_cat.id,'name',v_cat.name,'item_type',v_cat.item_type,'quantity',v_qty,'unit_price',v_price,'line_total',v_line,'variant_material_id',v_item->'variant_material_id'));
  end loop;
  v_total:=round(v_gross-round(v_gross*coalesce(p_discount_percent,0)/100,2),2);
  insert into public.sales_branch_order_counters(branch_id,next_number) values(v_shift.branch_id,1000) on conflict(branch_id) do nothing;
  select next_number into v_min from public.sales_branch_order_counters where branch_id=v_shift.branch_id for update;
  select greatest(v_min, coalesce(max(s.order_number)+1,v_min)) into v_min from public.sales s where s.branch_id=v_shift.branch_id;
  v_order:=case when p_order_number is null or p_order_number<v_min then v_min else p_order_number end;
  while exists(select 1 from public.sales s where s.branch_id=v_shift.branch_id and s.order_number=v_order)
     or exists(select 1 from public.pickup_orders o where o.branch_id=v_shift.branch_id and o.order_number=v_order and o.status='pending') loop
    v_order:=v_order+1;
  end loop;
  update public.sales_branch_order_counters set next_number=greatest(next_number,v_order+1),updated_at=now() where branch_id=v_shift.branch_id;
  insert into public.pickup_orders(branch_id,shift_id,employee_id,order_number,items,gross_total,discount_percent,total,customer_id,client_name,client_phone,comment)
  values(v_shift.branch_id,v_shift.id,p_employee_id,v_order,v_items,v_gross,coalesce(p_discount_percent,0),v_total,p_customer_id,
    nullif(trim(coalesce(p_client_name,'')),''),nullif(trim(coalesce(p_client_phone,'')),''),nullif(trim(coalesce(p_comment,'')),''));
  return v_order;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_hold_pickup_v2(p_shift_id bigint, p_employee_id bigint, p_items jsonb, p_discount_percent numeric DEFAULT 0, p_comment text DEFAULT NULL::text, p_order_number bigint DEFAULT NULL::bigint, p_customer_id uuid DEFAULT NULL::uuid, p_client_name text DEFAULT NULL::text, p_client_phone text DEFAULT NULL::text, p_client_order_ref text DEFAULT NULL::text)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_order bigint;
begin
  if p_customer_id is null and nullif(trim(coalesce(p_client_name,'')),'') is null and nullif(trim(coalesce(p_client_phone,'')),'') is null then
    raise exception 'Укажите контакт клиента: Telegram, Max или телефон';
  end if;
  v_order:=public.sales_hold_pickup(p_shift_id,p_employee_id,p_items,p_discount_percent,p_comment,p_order_number,p_customer_id,p_client_name,p_client_phone);
  update public.pickup_orders set client_order_ref=nullif(trim(coalesce(p_client_order_ref,'')),'')
  where id=(select max(id) from public.pickup_orders where order_number=v_order and status='pending' and shift_id=p_shift_id);
  return v_order;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_mark_link_payment(p_sale_id bigint, p_paid boolean)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if p_paid then
    update public.sales set payment_status='paid', paid_at=now()
    where id=p_sale_id and payment_method='link' and status='completed';
  else
    update public.sales set payment_status='unpaid', cancelled_at=now(), status='returned'
    where id=p_sale_id and payment_method='link' and status='completed';
  end if;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sales_next_order_number(p_branch_id bigint)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_next bigint;
begin
  insert into public.sales_branch_order_counters(branch_id,next_number)
  values(p_branch_id,1000) on conflict(branch_id) do nothing;
  select next_number into v_next from public.sales_branch_order_counters where branch_id=p_branch_id;
  return v_next;
end; $function$;

CREATE OR REPLACE FUNCTION public.sales_open_or_join_shift(p_branch_id bigint, p_employee_id bigint)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_shift_id bigint; v_emp_id bigint;
begin
  perform pg_advisory_xact_lock(p_branch_id);
  select id into v_shift_id from public.sales_shifts where branch_id=p_branch_id and status='open' order by started_at limit 1 for update;
  if v_shift_id is null then
    insert into public.sales_shifts(branch_id,employee_id) values(p_branch_id,p_employee_id) returning id into v_shift_id;
  end if;
  insert into public.sales_shift_employees(shift_id,employee_id,is_lead)
  values(v_shift_id,p_employee_id,false) on conflict(shift_id,employee_id) do nothing;
  return v_shift_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.sales_open_team_shift(p_branch_id bigint, p_person_ids bigint[], p_lead_person_id bigint DEFAULT NULL::bigint, p_expected_shift_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_shift_id bigint; v_person_id bigint; v_employee_id bigint; v_lead_id bigint; v_count integer;
begin
  perform pg_advisory_xact_lock(p_branch_id);
  if not exists(select 1 from public.sales_branches where id=p_branch_id and is_active) then
    raise exception 'Филиал не найден или отключён';
  end if;
  if coalesce(cardinality(p_person_ids),0)=0 or array_position(p_person_ids,null) is not null then
    raise exception 'Выберите хотя бы одного сотрудника';
  end if;
  select id into v_shift_id from public.sales_shifts where branch_id=p_branch_id and status='open' for update;
  if p_expected_shift_id is not null and v_shift_id is distinct from p_expected_shift_id then
    raise exception 'Смена уже закрыта или изменилась. Откройте рабочее место заново.';
  end if;
  for v_person_id in select distinct unnest(p_person_ids) order by 1 loop
    select p.employee_id into v_employee_id from public.sales_shift_employees p
      join public.sales_employees e on e.id=p.employee_id
      where p.shift_id=v_shift_id and e.person_id=v_person_id;
    if v_employee_id is null then
      v_employee_id:=(public.sales_ensure_employee(v_person_id,p_branch_id)->>'id')::bigint;
    end if;
    if v_shift_id is null then
      insert into public.sales_shifts(branch_id,employee_id) values(p_branch_id,v_employee_id) returning id into v_shift_id;
    end if;
    insert into public.sales_shift_employees(shift_id,employee_id,is_lead)
      values(v_shift_id,v_employee_id,false) on conflict(shift_id,employee_id) do nothing;
  end loop;
  select count(*) into v_count from public.sales_shift_employees where shift_id=v_shift_id;
  if v_count=1 then
    select employee_id into v_lead_id from public.sales_shift_employees where shift_id=v_shift_id;
  elsif p_lead_person_id is not null then
    select p.employee_id into v_lead_id from public.sales_shift_employees p
      join public.sales_employees e on e.id=p.employee_id
      where p.shift_id=v_shift_id and e.person_id=p_lead_person_id;
    if v_lead_id is null then raise exception 'Главный по ретуши должен быть участником смены'; end if;
  end if;
  if v_lead_id is not null then
    update public.sales_shift_employees set is_lead=false where shift_id=v_shift_id and is_lead;
    update public.sales_shift_employees set is_lead=true where shift_id=v_shift_id and employee_id=v_lead_id;
  end if;
  return public.sales_get_shift_context(v_shift_id);
end $function$;

CREATE OR REPLACE FUNCTION public.sales_pay_pickup(p_pickup_id bigint, p_shift_id bigint, p_employee_id bigint, p_payment_method text, p_comment text, p_items jsonb, p_loyalty_customer_id uuid DEFAULT NULL::uuid, p_loyalty_points numeric DEFAULT 0, p_loyalty_name text DEFAULT NULL::text, p_loyalty_phone text DEFAULT NULL::text, p_loyalty_comment text DEFAULT NULL::text, p_discount_percent numeric DEFAULT 0, p_payments jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_o public.pickup_orders%rowtype; v_order bigint; v_branch bigint; v_sale bigint;
begin
  select * into v_o from public.pickup_orders where id=p_pickup_id for update;
  if not found or v_o.status<>'pending' then raise exception 'Заказ уже оплачен или отменён'; end if;
  select branch_id into v_branch from public.sales_shifts where id=p_shift_id;
  perform set_config('polaroid.pickup_order',case when v_branch=v_o.branch_id then v_o.order_number::text else '' end,true);
  v_order:=public.sales_create_sale(p_shift_id,p_employee_id,p_payment_method,p_comment,p_items,p_loyalty_customer_id,p_loyalty_points,
    p_loyalty_name,p_loyalty_phone,p_loyalty_comment,case when v_branch=v_o.branch_id then v_o.order_number else null end,p_discount_percent,p_payments);
  perform set_config('polaroid.pickup_order','',true);
  select id into v_sale from public.sales where branch_id=v_branch and order_number=v_order order by id desc limit 1;
  update public.pickup_orders set status='paid',paid_at=now(),paid_shift_id=p_shift_id,sale_id=v_sale where id=p_pickup_id;
  return v_order;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_return_sale(p_sale_id bigint, p_shift_id bigint, p_comment text)
 RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_sale public.sales%rowtype; v_shift public.sales_shifts%rowtype;
begin
  select * into v_shift from public.sales_shifts where id=p_shift_id and status='open';
  if not found then raise exception 'Смена не найдена или закрыта'; end if;
  select * into v_sale from public.sales where id=p_sale_id for update;
  if not found then raise exception 'Продажа не найдена'; end if;
  if v_sale.status='returned' then raise exception 'Эта продажа уже возвращена'; end if;
  update public.sales set status='returned', returned_at=now() where id=v_sale.id;
  insert into public.sales_returns(sale_id,shift_id,branch_id,employee_id,amount,comment)
  values(v_sale.id,v_shift.id,v_shift.branch_id,v_shift.employee_id,v_sale.total,nullif(trim(coalesce(p_comment,'')),''));
  return v_sale.total;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sales_set_close_cash(p_shift_id bigint, p_employee_id bigint, p_amount numeric)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if p_amount is null or p_amount<0 then raise exception 'Укажите остаток наличных в кассе'; end if;
  if not exists(select 1 from public.sales_shift_employees se join public.sales_shifts s on s.id=se.shift_id
                where se.shift_id=p_shift_id and se.employee_id=p_employee_id and s.status='open') then
    raise exception 'Смена закрыта или сотрудник не участвует в смене'; end if;
  update public.sales_shifts set close_cash=round(p_amount,2),close_cash_employee_id=p_employee_id where id=p_shift_id;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_set_open_cash(p_shift_id bigint, p_employee_id bigint, p_amount numeric)
 RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_expected numeric(12,2); v_branch bigint;
begin
  if p_amount is null or p_amount<0 then raise exception 'Укажите сумму наличных в кассе'; end if;
  select branch_id into v_branch from public.sales_shifts where id=p_shift_id and status='open';
  if not found then raise exception 'Смена не найдена или уже закрыта'; end if;
  if not exists(select 1 from public.sales_shift_employees where shift_id=p_shift_id and employee_id=p_employee_id) then raise exception 'Сотрудник не участвует в смене'; end if;
  select close_cash into v_expected from public.sales_shifts where branch_id=v_branch and id<>p_shift_id and status='closed' and close_cash is not null order by ended_at desc nulls last limit 1;
  update public.sales_shifts set open_cash=round(p_amount,2),open_cash_expected=v_expected,open_cash_at=now(),open_cash_employee_id=p_employee_id where id=p_shift_id;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.sales_shift_cash_info(p_shift_id bigint)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select jsonb_build_object('shiftId',s.id,'openCash',s.open_cash,'openCashExpected',s.open_cash_expected,'closeCash',s.close_cash,
    'cashSales',(select coalesce(sum(p.amount),0) from public.sale_payments p join public.sales x on x.id=p.sale_id
                 where x.shift_id=s.id and x.status='completed' and p.payment_method='cash'),
    'prev',(select jsonb_build_object('shiftId',v.id,'closeCash',v.close_cash,'endedAt',v.ended_at,
              'closedBy',(select coalesce(pp.name,e.name) from public.sales_employees e left join public.sales_people pp on pp.id=e.person_id where e.id=v.close_cash_employee_id))
            from public.sales_shifts v where v.branch_id=s.branch_id and v.id<>s.id and v.status='closed' and v.close_cash is not null
            order by v.ended_at desc nulls last limit 1))
  from public.sales_shifts s where s.id=p_shift_id;
$function$;

CREATE OR REPLACE FUNCTION public.sales_shift_set_no_pay(p_shift_id bigint, p_no_pay boolean)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Требуется вход сотрудника'; end if;
  update public.sales_shifts set no_pay=coalesce(p_no_pay,false) where id=p_shift_id and status='open';
  if not found then raise exception 'Смена не найдена или уже закрыта'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.staff_request_guard()
 RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
declare r text := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', current_user);
begin
  if r in ('service_role', 'supabase_admin', 'postgres') then return; end if;
  if r = 'authenticated' and public.is_staff() then return; end if;
  raise sqlstate 'PT401' using message = 'Требуется вход сотрудника';
end $function$;
set check_function_bodies = off;
CREATE OR REPLACE FUNCTION public.stock_actor(p_shift_id bigint, p_person_id bigint, OUT is_admin boolean, OUT branch_id bigint, OUT person_name text)
 RETURNS record LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  is_admin:=public.is_admin();
  select s.branch_id, coalesce(pp.name,e.name) into branch_id, person_name
    from public.sales_shift_employees se join public.sales_employees e on e.id=se.employee_id
    join public.sales_shifts s on s.id=se.shift_id left join public.sales_people pp on pp.id=e.person_id
    where se.shift_id=p_shift_id and e.person_id=p_person_id and s.status='open' limit 1;
  if branch_id is null and not is_admin then raise exception 'Откройте смену: складские операции делает сотрудник смены или администратор'; end if;
  if is_admin and person_name is null then person_name:='Администратор'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_archive_material(p_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_norms set active=false where material_id in (select id from public.stock_materials where id=p_id or parent_id=p_id);
  update public.stock_materials set archived=true, is_active=false, name=name||' (удалён №'||id||')'
   where (id=p_id or parent_id=p_id) and not archived;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_cancel_operation(p_move_id bigint)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_g uuid; v_n int;
begin
  if not public.is_admin() then raise exception 'Отменить операцию может только администратор'; end if;
  select group_id into v_g from public.stock_moves where id=p_move_id and kind<>'sale' and cancelled_at is null;
  if v_g is null then raise exception 'Операция не найдена (списание по продаже меняется через выполняющий филиал)'; end if;
  update public.stock_moves set cancelled_at=now() where group_id=v_g and cancelled_at is null; get diagnostics v_n=row_count; return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_journal(p_branch_id bigint DEFAULT NULL::bigint, p_material_id bigint DEFAULT NULL::bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_kind text DEFAULT NULL::text, p_limit integer DEFAULT 300)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x.created_at desc, x.id desc),'[]') from (
    select m.id, m.created_at, m.kind, m.qty, m.counted, m.price_total, m.supplier, m.comment, m.person_name, m.branch_id, m.other_branch_id,
      m.material_id, mt.name material, mt.unit, m.sale_id, s.order_number, s.branch_id sale_branch_id, i.item_name
    from public.stock_moves m join public.stock_materials mt on mt.id=m.material_id
    left join public.sales s on s.id=m.sale_id left join public.sale_items i on i.id=m.sale_item_id
    where m.cancelled_at is null and (p_branch_id is null or m.branch_id=p_branch_id) and (p_material_id is null or m.material_id=p_material_id)
      and (p_from is null or m.created_at>=p_from) and (p_to is null or m.created_at<p_to)
      and (p_kind is null or m.kind=p_kind or (p_kind='transfer' and m.kind in ('transfer_in','transfer_out')))
    order by m.created_at desc, m.id desc limit least(greatest(coalesce(p_limit,300),1),2000)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.stock_operation(p_shift_id bigint, p_person_id bigint, p_kind text, p_branch_id bigint, p_items jsonb, p_to_branch_id bigint DEFAULT NULL::bigint, p_supplier text DEFAULT NULL::text, p_comment text DEFAULT NULL::text)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare a record; it jsonb; v_m bigint; v_q numeric; v_bal numeric; v_g uuid:=gen_random_uuid(); v_n int:=0;
begin
  select * into a from public.stock_actor(p_shift_id,p_person_id);
  if p_kind not in ('receipt','transfer','writeoff','inventory') then raise exception 'Неизвестная операция'; end if;
  if p_branch_id is null or not exists(select 1 from public.sales_branches where id=p_branch_id) then raise exception 'Выберите филиал'; end if;
  if p_kind='transfer' then
    if p_to_branch_id is null or p_to_branch_id=p_branch_id or not exists(select 1 from public.sales_branches where id=p_to_branch_id) then raise exception 'Выберите, в какой филиал передаёте'; end if;
    if not a.is_admin and a.branch_id not in (p_branch_id,p_to_branch_id) and coalesce(public.stock_workshop_id(),0) not in (p_branch_id,p_to_branch_id) then raise exception 'Перемещение должно быть с вашего филиала или на ваш филиал'; end if;
  elsif not a.is_admin and a.branch_id<>p_branch_id and p_branch_id<>coalesce(public.stock_workshop_id(),0) then raise exception 'Сотрудник смены работает только со складом своего филиала';
  end if;
  if p_kind='writeoff' and nullif(trim(coalesce(p_comment,'')),'') is null then raise exception 'Укажите причину списания'; end if;
  for it in select * from jsonb_array_elements(coalesce(p_items,'[]')) loop
    v_m:=(it->>'material_id')::bigint; v_q:=nullif(it->>'qty','')::numeric;
    if v_m is null or v_q is null then continue; end if;
    if not exists(select 1 from public.stock_materials where id=v_m) then raise exception 'Материал не найден'; end if;
    if p_kind='inventory' then
      if v_q<0 then raise exception 'Количество не может быть отрицательным'; end if;
      perform pg_advisory_xact_lock(hashtext('stock:'||v_m||':'||p_branch_id));
      select coalesce(sum(qty),0) into v_bal from public.stock_moves where material_id=v_m and branch_id=p_branch_id and cancelled_at is null;
      insert into public.stock_moves(material_id,branch_id,qty,kind,group_id,counted,comment,person_id,person_name,shift_id)
        values(v_m,p_branch_id,v_q-v_bal,'inventory',v_g,v_q,p_comment,p_person_id,a.person_name,p_shift_id);
    else
      if v_q<=0 then raise exception 'Количество должно быть больше нуля'; end if;
      if p_kind='receipt' then
        insert into public.stock_moves(material_id,branch_id,qty,kind,group_id,price_total,supplier,comment,person_id,person_name,shift_id)
          values(v_m,p_branch_id,v_q,'receipt',v_g,nullif(it->>'price_total','')::numeric,nullif(trim(coalesce(p_supplier,'')),''),p_comment,p_person_id,a.person_name,p_shift_id);
      elsif p_kind='writeoff' then
        insert into public.stock_moves(material_id,branch_id,qty,kind,group_id,comment,person_id,person_name,shift_id)
          values(v_m,p_branch_id,-v_q,'writeoff',v_g,p_comment,p_person_id,a.person_name,p_shift_id);
      else
        insert into public.stock_moves(material_id,branch_id,qty,kind,group_id,other_branch_id,comment,person_id,person_name,shift_id)
          values(v_m,p_branch_id,-v_q,'transfer_out',v_g,p_to_branch_id,p_comment,p_person_id,a.person_name,p_shift_id),
                (v_m,p_to_branch_id,v_q,'transfer_in',v_g,p_branch_id,p_comment,p_person_id,a.person_name,p_shift_id);
      end if;
    end if;
    v_n:=v_n+1;
  end loop;
  if v_n=0 then raise exception 'Добавьте хотя бы один материал с количеством'; end if;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_orders(p_branch_id bigint DEFAULT NULL::bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_order_number bigint DEFAULT NULL::bigint)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(o order by o.created_at desc),'[]') from (
    select s.id, s.order_number, s.created_at, s.branch_id, s.total, s.comment,
      (select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'name',i.item_name,'quantity',i.quantity,
          'moves',(select coalesce(jsonb_agg(jsonb_build_object('b',m.branch_id,'material',mt.name,'unit',mt.unit,'qty',-m.qty)),'[]')
                   from public.stock_moves m join public.stock_materials mt on mt.id=m.material_id where m.sale_item_id=i.id and m.kind='sale' and m.cancelled_at is null)) order by i.id),'[]')
       from public.sale_items i where i.sale_id=s.id) items
    from public.sales s
    where s.status<>'deleted' and (p_branch_id is null or s.branch_id=p_branch_id)
      and (p_order_number is null or s.order_number=p_order_number)
      and (p_order_number is not null or ((p_from is null or s.created_at>=p_from) and (p_to is null or s.created_at<p_to)))
    order by s.created_at desc limit 300
  ) o;
$function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_week()
 RETURNS date LANGUAGE sql STABLE
AS $function$ select date_trunc('week',(now() at time zone 'Europe/Moscow'))::date $function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_calc()
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  with mb as (
    select m.id material_id, m.name, m.unit, m.purchase_code, m.min_qty, m.pack_qty, m.pack_price, b.id branch_id
    from public.stock_materials m cross join public.sales_branches b
    where m.is_active and not m.no_track and cardinality(m.var_sizes)+cardinality(m.var_colors)=0 and ((not m.in_workshop and b.is_active is not false and not b.is_test and not b.is_workshop and (m.store_branch_id is null or m.store_branch_id=b.id)) or (m.in_workshop and b.is_workshop))
  ), x as (
    select mb.*, u.*,
      coalesce((select sum(qty) from public.stock_moves s where s.material_id=mb.material_id and s.branch_id=mb.branch_id and s.cancelled_at is null),0) balance,
      (select min(created_at) from public.stock_moves s where s.material_id=mb.material_id and s.branch_id=mb.branch_id and s.cancelled_at is null) first_at
    from mb cross join lateral (
      select coalesce(-sum(qty),0) used,
        coalesce(-sum(qty) filter (where created_at>=now()-interval '7 days'),0) w0,
        coalesce(-sum(qty) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days'),0) w1,
        coalesce(-sum(qty) filter (where created_at>=now()-interval '21 days' and created_at<now()-interval '14 days'),0) w2,
        coalesce(-sum(qty) filter (where created_at<now()-interval '21 days'),0) w3
      from public.stock_moves s where s.material_id=mb.material_id and s.branch_id=mb.branch_id and s.cancelled_at is null
        and s.kind in ('sale','writeoff') and s.created_at>=now()-interval '28 days') u
  ), d as (
    select x.*, greatest(extract(epoch from now()-greatest(first_at,now()-interval '28 days'))/86400,0) days from x
  ), y as (
    select d2.*, case
      when first_at is null then 0
      when n>=3 then case when mx>2*(sm-mx)/(n-1) and sm>mx then (sm-mx)/(n-1) else sm/n end
      else greatest(used,0)*7/greatest(days,1) end week_use
    from (select d1.*, (select sum(greatest(v,0)) from unnest((array[w0,w1,w2,w3])[1:n::int]) v) sm,
                 (select max(greatest(v,0)) from unnest((array[w0,w1,w2,w3])[1:n::int]) v) mx
          from (select d.*, least(4,ceil(days/7)) n from d) d1) d2
  ), z as (
    select y.*, (first_at is not null and balance<=0 and (used>0 or min_qty>0)) urgent,
      case when first_at is null then 0 else
        greatest(week_use + case when min_qty>0 then min_qty else coalesce(pack_qty,0) end - greatest(balance,0), 0) end raw
    from y
  ), w as (
    select z.*, case when urgent then greatest(raw,coalesce(pack_qty,1)) else raw end req from z
  ), v as (
    select w.*, case when pack_qty>0 then ceil(round(req/pack_qty,6)) end packs,
      case when pack_qty>0 then ceil(round(req/pack_qty,6))*pack_qty else ceil(round(req,6)) end need
    from w
  )
  select coalesce(jsonb_agg(r order by (r->>'urgent')::boolean desc, r->>'name'),'[]') from (
    select jsonb_build_object('material_id',material_id,'name',name,'unit',unit,'code',purchase_code,'min_qty',min_qty,
      'pack_qty',pack_qty,'pack_price',pack_price,'total',sum(need),'packs',sum(packs),
      'sum',case when pack_price>0 then coalesce(sum(packs),sum(need))*pack_price end,
      'urgent',bool_or(urgent),
      'branches',jsonb_agg(jsonb_build_object('b',branch_id,'balance',balance,'week_use',round(week_use::numeric,2),'need',need,'packs',packs,'urgent',urgent) order by branch_id)) r
    from v group by material_id,name,unit,purchase_code,min_qty,pack_qty,pack_price having sum(need)>0
  ) q;
$function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_build()
 RETURNS date LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_w date:=public.stock_purchase_week();
begin
  insert into public.stock_purchase_lists(week_start,created_at,rows) values(v_w,now(),public.stock_purchase_calc())
  on conflict (week_start) do update set created_at=excluded.created_at, rows=excluded.rows;
  return v_w;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_get(p_week date DEFAULT NULL::date, p_rebuild boolean DEFAULT false)
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_w date:=coalesce(p_week,public.stock_purchase_week()); r record;
begin
  if p_rebuild then
    if not public.is_admin() then raise exception 'Пересчитать может только администратор'; end if;
    v_w:=public.stock_purchase_build();
  elsif v_w=public.stock_purchase_week() and not exists(select 1 from public.stock_purchase_lists where week_start=v_w) then
    perform public.stock_purchase_build();
  end if;
  select * into r from public.stock_purchase_lists where week_start=v_w;
  return jsonb_build_object('week',v_w,'created_at',r.created_at,'rows',coalesce(r.rows,'[]'::jsonb),
    'weeks',(select coalesce(jsonb_agg(week_start order by week_start desc),'[]') from (select week_start from public.stock_purchase_lists order by week_start desc limit 30) w));
end $function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_hide_set(p_material_id bigint, p_hidden boolean)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Закупку отмечает администратор'; end if;
  insert into public.stock_purchase_hide(material_id,hidden,at) values(p_material_id,coalesce(p_hidden,true),now())
  on conflict (material_id) do update set hidden=excluded.hidden, at=excluded.at;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_purchase_live()
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  with c as (select x from jsonb_array_elements(public.stock_purchase_calc()) x),
  h as (select material_id from public.stock_purchase_hide where hidden)
  select jsonb_build_object('at',now(),
    'rows',(select coalesce(jsonb_agg(x),'[]') from c where (x->>'material_id')::bigint not in (select material_id from h)),
    'hidden',(select coalesce(jsonb_agg(x),'[]') from c where (x->>'material_id')::bigint in (select material_id from h)),
    'requests',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'branch_id',r.branch_id,'person_name',r.person_name,'catalog_id',r.catalog_id,
        'material_id',r.material_id,'name',r.name,'qty',r.qty,'comment',r.comment,'status',r.status,'created_at',r.created_at,
        'unit',m.unit,'code',m.purchase_code) order by r.created_at),'[]')
      from public.stock_requests r left join public.stock_materials m on m.id=r.material_id where r.status in ('open','unavailable')));
$function$;

CREATE OR REPLACE FUNCTION public.stock_workshop_id()
 RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select id from public.sales_branches where is_workshop order by id limit 1
$function$;

CREATE OR REPLACE FUNCTION public.stock_redo_item(p_item_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare it record; v_branch bigint;
begin
  select branch_id into v_branch from public.stock_moves where sale_item_id=p_item_id and kind='sale' and cancelled_at is null and branch_id<>coalesce(public.stock_workshop_id(),0) and material_id not in (select id from public.stock_materials where store_branch_id is not null) order by id limit 1;
  update public.stock_moves set cancelled_at=now() where sale_item_id=p_item_id and kind='sale' and cancelled_at is null;
  select i.*, s.branch_id sale_branch, s.status sale_status, s.created_at sale_at into it
    from public.sale_items i join public.sales s on s.id=i.sale_id where i.id=p_item_id;
  if not found or it.sale_status='deleted' or it.catalog_id is null or public.is_test_branch(coalesce(v_branch,it.sale_branch)) or public.is_test_branch(it.sale_branch) then return; end if;
  insert into public.stock_moves(material_id,branch_id,qty,kind,sale_id,sale_item_id,created_at)
  select n.material_id, case when m.in_workshop then public.stock_workshop_id() when m.store_branch_id is not null then m.store_branch_id else coalesce(v_branch,it.sale_branch) end, -(case when n.per_line then n.qty else n.qty*it.quantity end), 'sale', it.sale_id, it.id, coalesce(it.sale_at,now())
  from public.stock_norms n join public.stock_materials m on m.id=n.material_id where n.catalog_id=it.catalog_id and n.active and not m.no_track and cardinality(m.var_sizes)+cardinality(m.var_colors)=0 and coalesce(it.quantity,0)<>0;
  insert into public.stock_moves(material_id,branch_id,qty,kind,sale_id,sale_item_id,created_at)
  select m.id, case when m.in_workshop then public.stock_workshop_id() when m.store_branch_id is not null then m.store_branch_id else coalesce(v_branch,it.sale_branch) end, -it.quantity*coalesce((select n.qty from public.stock_norms n where n.material_id=m.parent_id and n.catalog_id=it.catalog_id and n.active limit 1),1), 'sale', it.sale_id, it.id, coalesce(it.sale_at,now())
  from public.stock_materials m where m.id=it.variant_material_id and coalesce(it.quantity,0)<>0;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_request_add(p_shift_id bigint, p_person_id bigint, p_branch_id bigint, p_name text, p_qty numeric, p_catalog_id bigint DEFAULT NULL::bigint, p_material_id bigint DEFAULT NULL::bigint, p_comment text DEFAULT NULL::text)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare a record; v_b bigint:=p_branch_id; v_id bigint;
begin
  select * into a from public.stock_actor(p_shift_id,p_person_id);
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Напишите, что нужно купить'; end if;
  if not a.is_admin then
    if v_b is null or (v_b<>a.branch_id and v_b is distinct from public.stock_workshop_id()) then v_b:=a.branch_id; end if;
  end if;
  insert into public.stock_requests(branch_id,person_name,catalog_id,material_id,name,qty,comment)
  values(v_b,a.person_name,p_catalog_id,p_material_id,trim(p_name),nullif(p_qty,0),nullif(trim(coalesce(p_comment,'')),''))
  returning id into v_id;
  return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_request_set(p_id bigint, p_status text)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Закупку отмечает администратор'; end if;
  if p_status not in ('open','bought','unavailable') then raise exception 'Неизвестный статус'; end if;
  update public.stock_requests set status=p_status, closed_at=case when p_status='open' then null else now() end where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_sale_extra(p_sale_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare s record;
begin
  select * into s from public.sales where id=p_sale_id;
  if not found or s.status is not distinct from 'dele'||'ted' or public.is_test_branch(s.branch_id) then return; end if;
  insert into public.stock_moves(material_id,branch_id,qty,kind,sale_id,created_at)
  select m.id, case when m.in_workshop then public.stock_workshop_id() when m.store_branch_id is not null then m.store_branch_id else s.branch_id end, -m.per_sale_qty, 'sale', s.id, coalesce(s.created_at,now())
  from public.stock_materials m
  where m.is_active and not m.no_track and m.per_sale_qty>0
    and not exists(select 1 from public.stock_moves x where x.sale_id=s.id and x.sale_item_id is null and x.material_id=m.id and x.kind='sale' and x.cancelled_at is null);
end $function$;

CREATE OR REPLACE FUNCTION public.stock_save_material(p_id bigint, p_name text, p_unit text, p_min_qty numeric, p_comment text, p_is_active boolean, p_norms jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Укажите название материала'; end if;
  if p_id is null then
    insert into public.stock_materials(name,unit,min_qty,comment,is_active)
      values(trim(p_name),coalesce(nullif(trim(p_unit),''),'шт'),coalesce(p_min_qty,0),nullif(trim(coalesce(p_comment,'')),''),coalesce(p_is_active,true)) returning id into v_id;
  else
    update public.stock_materials set name=trim(p_name),unit=coalesce(nullif(trim(p_unit),''),'шт'),min_qty=coalesce(p_min_qty,0),
      comment=nullif(trim(coalesce(p_comment,'')),''),is_active=coalesce(p_is_active,true) where id=p_id returning id into v_id;
    if v_id is null then raise exception 'Материал не найден'; end if;
  end if;
  if p_norms is not null then
    update public.stock_norms set active=false where material_id=v_id and active;
    insert into public.stock_norms(catalog_id,material_id,qty,active,per_line)
      select distinct on ((x->>'catalog_id')::bigint) (x->>'catalog_id')::bigint, v_id, (x->>'qty')::numeric, true, coalesce((x->>'per_line')::boolean,false)
      from jsonb_array_elements(p_norms) x where nullif(x->>'qty','')::numeric>0
    on conflict (catalog_id,material_id) do update set qty=excluded.qty, active=true, per_line=excluded.per_line;
  end if;
  return v_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_in_workshop(p_id bigint, p_on boolean)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set in_workshop=coalesce(p_on,false) where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_material_extra(p_id bigint, p_pack_qty numeric, p_pack_price numeric, p_per_sale_qty numeric)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set pack_qty=nullif(greatest(coalesce(p_pack_qty,0),0),0), pack_price=nullif(greatest(coalesce(p_pack_price,0),0),0),
    per_sale_qty=greatest(coalesce(p_per_sale_qty,0),0) where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_no_track(p_id bigint, p_on boolean)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set no_track=coalesce(p_on,false) where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_producer(p_shift_id bigint, p_person_id bigint, p_branch_id bigint, p_sale_id bigint DEFAULT NULL::bigint, p_sale_item_id bigint DEFAULT NULL::bigint)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare a record; v_n int;
begin
  select * into a from public.stock_actor(p_shift_id,p_person_id);
  if not exists(select 1 from public.sales_branches where id=p_branch_id) then raise exception 'Выберите филиал'; end if;
  if p_sale_item_id is null and p_sale_id is null then raise exception 'Не указан заказ'; end if;
  update public.stock_moves set branch_id=p_branch_id, person_id=p_person_id, person_name=a.person_name
   where kind='sale' and cancelled_at is null and branch_id<>coalesce(public.stock_workshop_id(),0) and ((p_sale_item_id is not null and sale_item_id=p_sale_item_id) or (p_sale_item_id is null and sale_id=p_sale_id));
  get diagnostics v_n=row_count; return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_producer_by_number(p_shift_id bigint, p_person_id bigint, p_sale_branch_id bigint, p_order_number bigint, p_branch_id bigint)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare v_sale bigint;
begin
  select id into v_sale from public.sales where branch_id=p_sale_branch_id and order_number=p_order_number and status<>'deleted' order by id desc limit 1;
  if v_sale is null then return -1; end if;
  return public.stock_set_producer(p_shift_id,p_person_id,p_branch_id,v_sale,null);
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_purchase_code(p_id bigint, p_code text)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set purchase_code=nullif(trim(coalesce(p_code,'')),'') where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_store_branch(p_id bigint, p_branch_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set store_branch_id=p_branch_id, in_workshop=case when p_branch_id is not null then false else in_workshop end
   where id=p_id or parent_id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_variant(p_id bigint, p_catalog_id bigint)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  update public.stock_materials set variant_catalog_id=p_catalog_id where id=p_id;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_set_variants(p_id bigint, p_sizes text[], p_colors text[])
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare p record; v_s text[]; v_c text[]; s text; c text; v_name text; v_child bigint; v_keep bigint[]:='{}';
begin
  if not public.is_admin() then raise exception 'Материалы настраивает администратор'; end if;
  select coalesce(array_agg(x order by o),'{}') into v_s from (select distinct on (trim(x)) trim(x) x, o from unnest(coalesce(p_sizes,'{}')) with ordinality u(x,o) where trim(x)<>'' order by trim(x),o) q;
  select coalesce(array_agg(x order by o),'{}') into v_c from (select distinct on (trim(x)) trim(x) x, o from unnest(coalesce(p_colors,'{}')) with ordinality u(x,o) where trim(x)<>'' order by trim(x),o) q;
  update public.stock_materials set var_sizes=v_s, var_colors=v_c, variant_catalog_id=case when cardinality(v_s)+cardinality(v_c)>0 then null else variant_catalog_id end where id=p_id;
  select * into p from public.stock_materials where id=p_id;
  if cardinality(v_s)+cardinality(v_c)>0 then
    foreach c in array (case when cardinality(v_c)>0 then v_c else array[null::text] end) loop
      foreach s in array (case when cardinality(v_s)>0 then v_s else array[null::text] end) loop
        v_name:=trim(p.name||coalesce(' '||c,'')||coalesce(' '||s,''));
        select id into v_child from public.stock_materials where parent_id=p_id and var_size is not distinct from s and var_color is not distinct from c order by id limit 1;
        if v_child is null then
          select id into v_child from public.stock_materials where name=v_name and id<>p_id and (parent_id is null or parent_id=p_id) order by id limit 1;
        end if;
        if v_child is null then
          insert into public.stock_materials(name,unit,min_qty,is_active) values(v_name,p.unit,p.min_qty,true) returning id into v_child;
        end if;
        update public.stock_materials set parent_id=p_id, var_size=s, var_color=c, name=v_name, unit=p.unit, min_qty=p.min_qty, is_active=p.is_active,
          in_workshop=p.in_workshop, store_branch_id=p.store_branch_id, no_track=p.no_track, pack_qty=p.pack_qty, pack_price=p.pack_price, purchase_code=p.purchase_code,
          variant_catalog_id=null, var_sizes='{}', var_colors='{}'
        where id=v_child;
        v_keep:=v_keep||v_child;
      end loop;
    end loop;
  end if;
  update public.stock_materials set is_active=false where parent_id=p_id and not (id=any(v_keep));
end $function$;

CREATE OR REPLACE FUNCTION public.stock_state(p_days integer DEFAULT 30)
 RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  select jsonb_build_object('workshop',(select jsonb_build_object('id',id,'name',name) from public.sales_branches where is_workshop order by id limit 1),
    'materials',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'name',m.name,'unit',m.unit,'min_qty',m.min_qty,'comment',m.comment,'purchase_code',m.purchase_code,'in_workshop',m.in_workshop,'store_branch_id',m.store_branch_id,'archived',m.archived,'pack_qty',m.pack_qty,'pack_price',m.pack_price,'per_sale_qty',m.per_sale_qty,'is_active',m.is_active,'no_track',m.no_track,'parent_id',m.parent_id,'var_size',m.var_size,'var_color',m.var_color,'var_sizes',m.var_sizes,'var_colors',m.var_colors,'variant_catalog_id',m.variant_catalog_id,
        'norms',(select coalesce(jsonb_agg(jsonb_build_object('catalog_id',n.catalog_id,'qty',n.qty,'per_line',n.per_line,'name',c.name) order by c.name),'[]')
                 from public.stock_norms n join public.sales_catalog c on c.id=n.catalog_id where n.material_id=m.id and n.active)) order by m.name),'[]') from public.stock_materials m),
    'balances',(select coalesce(jsonb_agg(jsonb_build_object('m',material_id,'b',branch_id,'q',q)),'[]')
                from (select material_id,branch_id,sum(qty) q from public.stock_moves where cancelled_at is null group by 1,2) x),
    'usage',(select coalesce(jsonb_agg(jsonb_build_object('m',material_id,'b',branch_id,'q',q)),'[]')
             from (select material_id,branch_id,-sum(qty) q from public.stock_moves where cancelled_at is null and kind in ('sale','writeoff') and created_at>=now()-make_interval(days=>greatest(p_days,1)) group by 1,2) x)
  );
$function$;

CREATE OR REPLACE FUNCTION public.stock_trg_sale()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
declare r record;
begin
  begin
    if new.status='deleted' and old.status is distinct from 'deleted' then
      update public.stock_moves set cancelled_at=now() where sale_id=new.id and kind='sale' and cancelled_at is null;
    elsif old.status='deleted' and new.status<>'deleted' then
      for r in select id from public.sale_items where sale_id=new.id loop perform public.stock_redo_item(r.id); end loop; perform public.stock_sale_extra(new.id);
    elsif new.created_at is distinct from old.created_at then
      update public.stock_moves set created_at=new.created_at where sale_id=new.id and kind='sale' and cancelled_at is null;
    end if;
  exception when others then raise warning 'stock: %', sqlerrm; end;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.stock_trg_sale_item()
 RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.stock_redo_item(new.id); perform public.stock_sale_extra(new.sale_id);
  exception when others then raise warning 'stock: %', sqlerrm; end;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.submit_test_attempt(p_test_id bigint, p_trainee_name text, p_score_percent numeric, p_extra_training_hours numeric, p_answers jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $function$
declare v_id bigint;
begin
  if not public.is_staff() then raise exception 'Нет доступа: войдите в аккаунт сотрудника'; end if;
  if coalesce(trim(p_trainee_name),'') = '' then raise exception 'Введите ФИО'; end if;
  insert into public.test_attempts(test_id, trainee_name, score_percent, extra_training_hours)
  values (p_test_id, trim(p_trainee_name), p_score_percent, p_extra_training_hours)
  returning id into v_id;
  insert into public.test_answers(attempt_id, question_id, trainee_answer, is_correct)
  select v_id, (x->>'question_id')::bigint, x->>'trainee_answer', (x->>'is_correct')::boolean
  from jsonb_array_elements(coalesce(p_answers,'[]'::jsonb)) x;
  return v_id;
end;
$function$;
CREATE TRIGGER customer_debts_from_payment AFTER INSERT ON public.sale_payments FOR EACH ROW EXECUTE FUNCTION customer_debts_from_payment();
CREATE TRIGGER stock_sale AFTER UPDATE OF status, created_at ON public.sales FOR EACH ROW EXECUTE FUNCTION stock_trg_sale();
CREATE TRIGGER announcement_track AFTER INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION announcement_track_products();
CREATE TRIGGER announcement_track AFTER INSERT OR UPDATE ON public.sales_catalog FOR EACH ROW EXECUTE FUNCTION announcement_track_catalog();
CREATE TRIGGER stock_sale_item AFTER INSERT OR UPDATE OF quantity, catalog_id, variant_material_id ON public.sale_items FOR EACH ROW EXECUTE FUNCTION stock_trg_sale_item();

